from __future__ import annotations

import json
import pathlib
import shutil
import subprocess


ROOT = pathlib.Path(__file__).resolve().parent
OCTAVE_SCRIPT = (
    ROOT / "source" / "sciencebench_task005" / "task005_public_reproduction.m"
)
OUTPUTS = ROOT / "outputs"
REPORT_PATH = OUTPUTS / "reproduction_report.json"
STANDARD_STATUSES = {
    "workflow_completed",
    "pre_fix_expected_failure",
    "post_fix_success",
    "runner_failure",
}


def emit_runner_failure(error_type: str, error: str) -> int:
    report = {
        "workflow": "edited MRS SDAT loading and common-reference diagnostics",
        "status": "runner_failure",
        "error_type": error_type,
        "error": error,
    }
    payload = json.dumps(report, indent=2, sort_keys=True, allow_nan=False) + "\n"
    OUTPUTS.mkdir(exist_ok=True)
    REPORT_PATH.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return 2


def load_report() -> dict[str, object]:
    def reject_constant(value: str) -> None:
        raise ValueError(f"Non-finite JSON constant: {value}")

    report = json.loads(
        REPORT_PATH.read_text(encoding="utf-8"), parse_constant=reject_constant
    )
    if not isinstance(report, dict) or report.get("status") not in STANDARD_STATUSES:
        raise ValueError("Octave report did not contain a standard public status.")
    return report


def main() -> int:
    OUTPUTS.mkdir(exist_ok=True)
    REPORT_PATH.unlink(missing_ok=True)
    octave = shutil.which("octave")
    if octave is None:
        return emit_runner_failure(
            "MissingDependency",
            "GNU Octave is required for this task. Run in the Octave task image.",
        )

    try:
        completed = subprocess.run(
            [octave, "--no-gui", "--quiet", str(OCTAVE_SCRIPT)],
            cwd=ROOT,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            check=False,
            timeout=120,
        )
    except subprocess.TimeoutExpired as exc:
        return emit_runner_failure(
            type(exc).__name__, "Octave public workflow timed out."
        )
    except OSError as exc:
        return emit_runner_failure(type(exc).__name__, str(exc))

    print(completed.stdout, end="")
    try:
        report = load_report()
    except (OSError, ValueError) as exc:
        return emit_runner_failure(type(exc).__name__, str(exc))

    if report["status"] == "runner_failure":
        return 2
    if completed.returncode != 0:
        return emit_runner_failure(
            "OctaveProcessError",
            f"Octave exited with code {completed.returncode} without a runner_failure report.",
        )
    return 0 if report["status"] in {"workflow_completed", "post_fix_success"} else 1


if __name__ == "__main__":
    raise SystemExit(main())

this_file = mfilename('fullpath');
helper_dir = fileparts(this_file);
source_root = fileparts(helper_dir);
task_root = fileparts(source_root);
warning('off', 'all');
outputs_dir = fullfile(task_root, 'outputs');
fixture_path = fullfile(task_root, 'fixtures', 'synthetic_edited_mrs_public.json');
if ~exist(outputs_dir, 'dir')
    mkdir(outputs_dir);
end

addpath(helper_dir);
report_path = fullfile(outputs_dir, 'reproduction_report.json');
exit_code = 0;

try
    result = task005_evaluate(source_root, fixture_path);
    report.dataset = result.case_name;
    report.workflow = 'edited MRS SDAT loading and common-reference diagnostics';
    report.num_subspectra = result.num_subspectra;
    report.input_observation = result.input_observation;
    report.loaded_output_valid = result.loaded_workflow.loaded_output_valid;
    report.loaded_observation = result.loaded_workflow.observation;
    report.status = 'workflow_completed';
catch err
    report.workflow = 'edited MRS SDAT loading and common-reference diagnostics';
    report.status = 'runner_failure';
    if isfield(err, 'identifier') && ~isempty(err.identifier)
        report.error_type = err.identifier;
    else
        report.error_type = 'OctaveError';
    end
    report.error = err.message;
    exit_code = 2;
end

payload = jsonencode(report);
fid = fopen(report_path, 'w');
if fid < 0
    error('sciencebench:task005:ReportWrite', 'Could not open reproduction report for writing.');
end
fprintf(fid, '%s\n', payload);
fclose(fid);

disp(payload);
if exit_code ~= 0
    exit(exit_code);
end

function result = task005_evaluate(source_root, fixture_path)
% Run the public edited-MRS loading experiment against the current source tree.

case_data = task005_load_case(fixture_path);
[ppm, spectra] = task005_build_spectra(case_data);
input_observation = task005_observe_spectra(ppm, spectra, case_data);
loaded_workflow = task005_run_loaded_workflow(source_root, ppm, spectra, case_data);

result.case_name = case_data.name;
result.num_subspectra = columns(spectra);
result.input_observation = input_observation;
result.loaded_workflow = loaded_workflow;
result.workflow_completed = loaded_workflow.workflow_completed;
end

function case_data = task005_load_case(fixture_path)
if exist(fixture_path, 'file') ~= 2
    error('sciencebench:task005:FixtureMissing', 'Public fixture not found: %s', fixture_path);
end

decoded = jsondecode(fileread(fixture_path));
scalar_fields = {
    'num_points', 'ppm_min', 'ppm_max', 'reference_center_ppm', ...
    'reference_width_ppm', 'edited_center_ppm', 'edited_width_ppm'
};
for idx = 1:numel(scalar_fields)
    field_name = scalar_fields{idx};
    if ~isfield(decoded, field_name)
        error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: %s', field_name);
    end
    value = decoded.(field_name);
    if ~isnumeric(value) || numel(value) ~= 1 || ~isfinite(value)
        error('sciencebench:task005:FixtureProtocol', 'Fixture field %s must be one finite number.', field_name);
    end
    case_data.(field_name) = double(value);
end

if ~isfield(decoded, 'name')
    error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: name');
end
case_data.name = char(decoded.name);

vector_fields = {'reference_amplitudes', 'edited_amplitudes', 'phase_degrees'};
for idx = 1:numel(vector_fields)
    field_name = vector_fields{idx};
    if ~isfield(decoded, field_name)
        error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: %s', field_name);
    end
    value = double(decoded.(field_name));
    if ~isnumeric(value) || isempty(value) || any(~isfinite(value(:)))
        error('sciencebench:task005:FixtureProtocol', 'Fixture field %s must contain finite numbers.', field_name);
    end
    case_data.(field_name) = reshape(value, 1, []);
end

nsubs = numel(case_data.reference_amplitudes);
if numel(case_data.edited_amplitudes) ~= nsubs || numel(case_data.phase_degrees) ~= nsubs
    error('sciencebench:task005:FixtureProtocol', 'Fixture subspectrum arrays must have equal lengths.');
end
if case_data.num_points < 16 || case_data.ppm_max <= case_data.ppm_min
    error('sciencebench:task005:FixtureProtocol', 'Fixture spectral grid is invalid.');
end
if case_data.reference_width_ppm <= 0 || case_data.edited_width_ppm <= 0
    error('sciencebench:task005:FixtureProtocol', 'Fixture peak widths must be positive.');
end
end

function [ppm, spectra] = task005_build_spectra(case_data)
npts = case_data.num_points;
ppm = linspace(case_data.ppm_min, case_data.ppm_max, npts)';
reference_shape = exp(-0.5 .* ((ppm - case_data.reference_center_ppm) ./ case_data.reference_width_ppm) .^ 2);
edited_shape = exp(-0.5 .* ((ppm - case_data.edited_center_ppm) ./ case_data.edited_width_ppm) .^ 2);

nsubs = numel(case_data.reference_amplitudes);
spectra = zeros(npts, nsubs);
for idx = 1:nsubs
    phase = case_data.phase_degrees(idx) * pi / 180;
    signal = case_data.reference_amplitudes(idx) .* reference_shape + ...
        case_data.edited_amplitudes(idx) .* edited_shape;
    spectra(:, idx) = real(signal .* complex(cos(phase), sin(phase)));
end
end

function metrics = task005_observe_spectra(ppm, spectra, case_data)
mask = task005_reference_mask(ppm, case_data.reference_center_ppm, case_data.reference_width_ppm);
window = real(spectra(mask, :));

polarities = zeros(1, columns(window));
for idx = 1:columns(window)
    polarities(idx) = task005_estimate_polarity(window(:, idx));
end
sign_consistency = mean(polarities == polarities(1));

norms = zeros(1, columns(window));
for idx = 1:columns(window)
    norms(idx) = norm(window(:, idx));
end
retained = norm(mean(window, 2)) / max(mean(norms), 1e-12);

metrics.reference_sign_consistency = sign_consistency;
metrics.retained_common_signal_ratio = retained;
metrics.reference_peak_polarity_consistent = all(polarities == polarities(1));
metrics.observations_finite = isfinite(sign_consistency) && isfinite(retained);
end

function mask = task005_reference_mask(ppm, center, width)
mask = abs(ppm - center) <= max(width * 3.5, 0.08);
end

function polarity = task005_estimate_polarity(spec)
[~, idx] = max(abs(real(spec)));
if real(spec(idx)) >= 0
    polarity = 1.0;
else
    polarity = -1.0;
end
end

function workflow = task005_run_loaded_workflow(source_root, ppm, spectra, case_data)
workflow = struct;

input_dir = fullfile(fileparts(source_root), 'outputs', 'public_sdat_study');
if ~exist(input_dir, 'dir')
    mkdir(input_dir);
end

addpath(fullfile(source_root, 'libraries', 'FID-A', 'inputOutput'));
data_path = task005_write_loader_fixture(input_dir, spectra);

loaded = io_loadspec_sdat(data_path, columns(spectra), 0);
if ~task005_valid_loaded_struct(loaded, columns(spectra))
    error('sciencebench:task005:LoaderProtocol', 'SDAT loader returned an invalid or non-finite payload.');
end

loaded_spectra = task005_average_loaded_spectra(loaded);
if rows(loaded_spectra) ~= numel(ppm) || columns(loaded_spectra) ~= columns(spectra)
    error('sciencebench:task005:LoaderProtocol', 'SDAT loader returned an unexpected spectral shape.');
end

workflow.observation = task005_observe_spectra(ppm, loaded_spectra, case_data);
if ~workflow.observation.observations_finite
    error('sciencebench:task005:LoaderProtocol', 'SDAT loader observations were non-finite.');
end
workflow.loaded_output_valid = true;
workflow.workflow_completed = true;
end

function ok = task005_valid_loaded_struct(value, expected_subspecs)
ok = isstruct(value) && isfield(value, 'fids') && isfield(value, 'specs') && ...
    isfield(value, 'dims') && isfield(value, 'subspecs') && value.subspecs == expected_subspecs && ...
    all(isfinite(value.fids(:))) && all(isfinite(value.specs(:)));
end

function spectra = task005_average_loaded_spectra(loaded)
spectra = loaded.specs;
if isfield(loaded.dims, 'averages') && loaded.dims.averages > 0
    spectra = mean(spectra, loaded.dims.averages);
end
spectra = squeeze(spectra);
if isvector(spectra)
    spectra = spectra(:);
end
end

function data_path = task005_write_loader_fixture(input_dir, spectra)
data_path = fullfile(input_dir, 'public_loader.sdat');
spar_path = fullfile(input_dir, 'public_loader.spar');

samples = rows(spectra);
subspecs = columns(spectra);
averages_per_subspec = 2;
rows_in_file = subspecs * averages_per_subspec;
source_fids = ifft(ifftshift(spectra, 1), [], 1);
fid_data = zeros(samples, rows_in_file);
for average_index = 1:averages_per_subspec
    for subspec_index = 1:subspecs
        row_index = (average_index - 1) * subspecs + subspec_index;
        fid_data(:, row_index) = source_fids(:, subspec_index);
    end
end

packed = zeros(2, samples, rows_in_file);
packed(1, :, :) = real(fid_data);
packed(2, :, :) = imag(fid_data);

fid = fopen(data_path, 'w', 'ieee-le');
if fid < 0
    error('Could not create public loader fixture.');
end
fwriteVAXG(fid, packed(:), 'float32');
fclose(fid);

fid = fopen(spar_path, 'w');
if fid < 0
    error('Could not create public loader metadata.');
end
fprintf(fid, 'samples : %d\n', samples);
fprintf(fid, 'rows : %d\n', rows_in_file);
fprintf(fid, 'averages : %d\n', rows_in_file);
fprintf(fid, 'synthesizer_frequency : 127731000\n');
fprintf(fid, 'sample_frequency : 2000\n');
fprintf(fid, 'echo_time : 68\n');
fprintf(fid, 'repetition_time : 2000\n');
fprintf(fid, 'scan_id : MEGA\n');
fprintf(fid, 'scan_date : 2026.07.13\n');
fprintf(fid, 'ap_size : 20\n');
fprintf(fid, 'lr_size : 20\n');
fprintf(fid, 'cc_size : 20\n');
fprintf(fid, 'ap_off_center : 0\n');
fprintf(fid, 'lr_off_center : 0\n');
fprintf(fid, 'cc_off_center : 0\n');
fprintf(fid, 'ap_angulation : 0\n');
fprintf(fid, 'lr_angulation : 0\n');
fprintf(fid, 'cc_angulation : 0\n');
fprintf(fid, 'patient_position : HFS\n');
fprintf(fid, 'patient_orientation : TRA\n');
fclose(fid);
end

%io_loadspec_sdat.m
%Jamie Near, McGill University 2014.
%Georg Oeltzschner, Johns Hopkins University 2018.
%
% USAGE:
% out=io_loadspec_sdat(filename,subspecs);
% 
% DESCRIPTION:
% Reads in Philips MRS data (.spar and .sdat files) using code adapted from 
% PhilipsRead.m, provided as part of the Gannet software package by Richard 
% Edden (gabamrs.com).
% 
% io_loadspec_sdat outputs the data in structure format, with fields 
% corresponding to time scale, fids, frequency scale, spectra, and header 
% fields containing information about the acquisition.  The resulting 
% matlab structure can be operated on by the other functions in this MRS 
% toolbox. ALSO:  This code is not currently smart enough to parse out all 
% of the relevant information from the header file, such as the number of 
% subspectra.  So for now, these details must be passed to the function as 
% input arguments.  Help implementing these improvements are most welcome!!
% 
% INPUTS:
% filename   = filename of Philips sdat file to be loaded.
% subspecs   = number of subspectra in the data (from spectral editing, ISIS, etc.)
%
% OUTPUTS:
% out        = Input dataset in FID-A structure format.

function out = io_loadspec_sdat(filename,subspecs,series)

if nargin<3
    series = 0;
end
% Read in the data and header information
[data, header] = philipsLoad(filename);

% Determine the dimensions of the data
data_size       = size(data);
dims.t          = find(data_size == header.samples);
if (header.rows > 1 && header.averages > 1) && series
    if length(data_size) > 2 % Data has averages and series
        dims.averages   = find(data_size == header.averages);
        dims.extras   = find(data_size == header.rows);
    else % Data has a series stored
        dims.averages   = 0;
        dims.extras   = find(data_size == header.rows);
    end
else
    dims.averages   = find(data_size == header.rows);
end
dims.coils      = 0; % SDAT is already coil-combined
% Now arrange in the standard order (samples-avgs-subspecs):
if (isfield(header, 'nr_of_slices_for_multislice') && header.nr_of_slices_for_multislice > 1) && (isfield(header, 'dim2_pnts') && header.dim2_pnts' > 1)
    data = permute(data ,[dims.t dims.averages dims.Zvoxels]);  
    dims.Zvoxels = 3;
    dims.averages = 2;
    dims.extras = 0;
else if (header.rows > 1 && header.averages > 1) && series
        if length(data_size) > 2 % Data has averages and series
            data = permute(data ,[dims.t dims.extras dims.averages]);
            dims.averages = 2;
            dims.extras = 3;
        else % Data has a series stored
            data = permute(data ,[dims.t dims.extras]);
            dims.averages = 0;
            dims.extras = 2;
        end
    else
        data = permute(data ,[dims.t dims.averages]);
        dims.averages = 2;
        dims.extras = 0;
    end
end

dims.t = 1;


% We have no way of actually knowing the number of sub-spectra (e.g. for 
% MEGA-PRESS or HERMES acquisitions, so we will split the averages 
% according to the 'subspecs' input.
% Initialize fids array:
fids = squeeze(zeros(header.samples, header.rows/subspecs, subspecs));
% Remove phase cycle
fids = fids .* repmat(conj(fids(1,:,:,:))./abs(fids(1,:,:,:)),[size(fids,1) 1]);
if subspecs == 2
    %Split the subspectra out of the "averages" dimension:
    fids(:,:,1) = data(:,[1:2:end]);
    fids(:,:,2) = data(:,[2:2:end]);
elseif subspecs == 4
    fids(:,:,1) = data(:,[1:4:end]);
    fids(:,:,2) = data(:,[2:4:end]);
    fids(:,:,3) = data(:,[3:4:end]);
    fids(:,:,4) = data(:,[4:4:end]);
else
    fids = data;
end

if subspecs > 1
    dims.subSpecs = 3;
else
    dims.subSpecs = 0;
end

sz = size(fids);

% Fill in the header information
txfrq = header.synthesizer_frequency; % transmitter frequency [Hz]
Bo = txfrq/42577000; % B0 [T]
averages = size(fids,2)*size(fids,3); % number of rows in the file
rawAverages = averages;
spectralwidth = header.sample_frequency; % bandwidth [Hz]
dwelltime = 1/spectralwidth; % dwelltime [s]
te = header.echo_time; % echo time [ms]
tr = header.repetition_time; % repetition time [ms]
sequence = header.scan_id; % sequence type
Ncoils = 1; % SDAT already coil-combined
rawSubspecs = subspecs;
date = header.scan_date; % scan date [yyyy.mm.dd hh:mm:ss]
geometry.size.ap = header.ap_size; % voxel size in AP direction [mm]
geometry.size.lr = header.lr_size; % voxel size in LR direction [mm]
geometry.size.cc = header.cc_size; % voxel size in CC direction [mm]
geometry.pos.ap = header.ap_off_center; % voxel center offset in AP direction [mm]
geometry.pos.lr = header.lr_off_center; % voxel center offset in LR direction [mm]
geometry.pos.cc = header.cc_off_center; % voxel center offset in CC direction [mm]
geometry.rot.ap = header.ap_angulation; % angulation around AP axis [deg]
geometry.rot.lr = header.lr_angulation; % angulation around LR axis [deg]
geometry.rot.cc = header.cc_angulation; % angulation around CC axis [deg]

% Produce specs
specs = fftshift(fft(fids,[],dims.t),dims.t);
% Calculate t and ppm arrays using the calculated parameters:
f = [(-spectralwidth/2)+(spectralwidth/(2*sz(1))):spectralwidth/(sz(1)):(spectralwidth/2)-(spectralwidth/(2*sz(1)))];
ppm = f/(Bo*42.577);

% Philips data assumes the center frequency to be 4.68 ppm:
centerFreq = 4.68;
ppm=ppm + centerFreq;

t = [0:dwelltime:(sz(1)-1)*dwelltime];

%FILLING IN DATA STRUCTURE
out.fids=fids;
out.specs=specs;
out.sz=sz;
out.ppm=ppm;  
out.t=t;    
out.spectralwidth=spectralwidth;
out.dwelltime=dwelltime;
out.txfrq=txfrq;
out.date=date;
out.dims=dims;
out.Bo=Bo;
out.averages=averages;
out.rawAverages=rawAverages;
out.subspecs=subspecs;
out.rawSubspecs=rawSubspecs;
out.seq=sequence;
out.te=te;
out.tr=tr;
out.pointsToLeftshift=0;
out.centerFreq = centerFreq;
out.geometry = geometry;
if isfield(header,'nucleus')
    out.nucleus = header.nucleus;
end
if isfield(header,'equipment_sw_verions')
    out.software = ['R ' header.equipment_sw_verions];
end
%FILLING IN DATA STRUCUTRE FOR SDAT MRSI
if isfield(header, 'dim2_pnts')
    out.nXvoxels = header.dim2_pnts;
    out.flags.MultiVoxel=1;
end
if isfield(header, 'dim3_pnts')
    out.nYvoxels = header.dim3_pnts;
    out.flags.MultiVoxel=1;
end
if isfield(header, 'nr_of_slices_for_multislice') && isfield(header, 'dim2_pnts');
    out.nZvoxels = header.nr_of_slices_for_multislice;
    out.flags.MultiVoxel=1;
end

%FILLING IN THE FLAGS
out.flags.writtentostruct=1;
out.flags.gotparams=1;
out.flags.leftshifted=0;
out.flags.filtered=0;
out.flags.zeropadded=0;
out.flags.freqcorrected=0;
out.flags.phasecorrected=0;
out.flags.averaged=0;
out.flags.addedrcvrs=1;
out.flags.subtracted=0;
out.flags.writtentotext=0;
out.flags.downsampled=0;
if out.dims.subSpecs==0
    out.flags.isFourSteps=0;
else
    out.flags.isFourSteps=(out.sz(out.dims.subSpecs)==4);
end
if dims.extras > 0 % Is a series
   out.extras = out.sz(dims.extras);
   extra_names = {};
   seq = {};
   for ex = 1 : out.sz(dims.extras)
       extra_names{ex} = ['Exp_' num2str(ex)];
       seq{ex} = out.seq;
   end
   out.extra_names = extra_names;
   if dims.averages == 0
      out.averages=1;
      out.flags.averaged = 1;
   end
   out.spectralwidth = ones(1,out.extras)*spectralwidth;
   out.dwelltime = ones(1,out.extras)*dwelltime;
   out.txfrq = ones(1,out.extras)*txfrq;
   out.exp_var = ones(1,out.extras);
   out.seq = seq;
   out.te = ones(1,out.extras)*te;
   out.tr = ones(1,out.extras)*tr;
   out.pointsToLeftshift = zeros(1,out.extras);
   out.centerFreq = ones(1,out.extras)*centerFreq;   
   out.flags.isSeries = 1;
   out.flags.MultiVoxel=0;
end
% Add info for niiwrite
out.PatientPosition = strrep([header.patient_position ' ' header.patient_orientation],'"','');
out.Manufacturer = 'Philips';
[~,filename,ext] = fileparts(filename);
out.OriginalFile = [filename ext];
% Sequence flags
out.flags.isUnEdited = 0;
out.flags.isMEGA = 0;
out.flags.isHERMES = 0;
out.flags.isHERCULES = 0;
out.flags.isPRIAM = 0;
out.flags.isMRSI = 0;
%DONE

function [out,switchOrder] = osp_onOffClassifyMEGA(in, target,Order)
%% [outA,switchOrder] = osp_onOffClassifyMEGA(in,target)
%   This function decides which of the two provided MEGA sub-spectra in the
%   are the edit-ON or the edit-OFF.
%
%   To this end, the difference spectrum is analyzed. For GABA-edited data,
%   the NAA peak is investigated; for GSH-edited data, the residual water
%   peak.
%
%   The function then assigns the edit-OFF spectrum to field A, and the
%   edit-ON spectrum to field B.
%
%   USAGE:
%       [out] = osp_onOffClassifyMEGA(in, target, Order)
%
%   INPUTS:
%       in     = FID-A structure containing MEGA spectrum.
%       target  = String. Can be 'GABA' or 'GSH'.
%       Order = manually overwrite order
%
%   OUTPUTS:
%       out    = FID-A structure containing the ordered MEGA sub-spectrum.
%       switchOrder = Vector indicating the order in which the input
%               spectra are rearranged in order to generate the output order.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-03-18)
%       goeltzs1@jhmi.edu
%           
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-03-18: First version of the code.
%       2020-01-15: Modified by Helge Zoellner (absolute value
%       implementation)

if nargin < 2
    target = 'GABA';
    Order = [];
end
if nargin < 3
    Order = [];
end
out = in;
if isempty(Order)
    switch target
        case 'GABA'
            % Determine which of the differences has an upright NAA peak
            temp = op_freqrange(in, 1.7, 2.3);        
        case 'GSH'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 4, 5);
        case 'Lac'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 3.8, 4);
        case 'PE398'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 3.8, 4.1);       
        case 'PE322'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 3.0, 3.3);     
        otherwise
            disp('MEGA ON/OFF classifier does not recognize the input argument ''target''. We automatically assume no reordering. You can change that in osp_onOFFClassifyMEGA.m');
             outA = inA;
            outB = inB;
            switchOrder = 0;
    end

    spec = abs(real(temp.specs));        
    max_diffAB = max(spec(:,1) - spec(:,2));
    max_diffBA = max(spec(:,2) - spec(:,1));


    if max_diffAB > max_diffBA

        switchOrder = 0;
    else
        temp = in;
        out.specs(:,1) = temp.specs(:,2);
        out.specs(:,2) = temp.specs(:,1);
        out.fids(:,1) = temp.fids(:,2);
        out.fids(:,2) = temp.fids(:,1);
        switchOrder = 1;
    end
else
    switchOrder = Order;
    if switchOrder
        temp = in;
        out.specs(:,1) = temp.specs(:,2);
        out.specs(:,2) = temp.specs(:,1);
        out.fids(:,1) = temp.fids(:,2);
        out.fids(:,2) = temp.fids(:,1);
    end
end

end

function [MRSCont] = osp_LoadSDAT(MRSCont)
%% [MRSCont] = osp_LoadSDAT(MRSCont)
%   This function reads raw (but coil-combined) data from Philips SDAT files.
%
%   USAGE:
%       [MRSCont] = osp_LoadSDAT(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-20)
%       goeltzs1@jhmi.edu
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-02-20: First version of the code.

% Close any remaining open figures
close all;
warning('off','all');
if MRSCont.flags.hasMM %re_mm adding functionality to load MM data
    if ((length(MRSCont.files_mm) == 1) && (MRSCont.nDatasets(1)>1))   %re_mm seems like specificy one MM file for a batch is also an option to plan to accomodate
        for kk=2:MRSCont.nDatasets(1) %re_mm 
            MRSCont.files_mm{kk} = MRSCont.files_mm{1}; % re_mm allowable to specify one MM file for the whole batch
        end %re_mm 
    end   %re_mm 
    if ((length(MRSCont.files_mm) ~= MRSCont.nDatasets(1)) )   %re_mm 
        msg = 'Number of specified MM files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end   %re_mm 
end   %re_mm 
if MRSCont.flags.hasRef
    if length(MRSCont.files_ref) ~= MRSCont.nDatasets(1)
        msg = 'Number of specified reference files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end
end
if MRSCont.flags.hasWater
    if length(MRSCont.files_w) ~= MRSCont.nDatasets(1)
        msg = 'Number of specified water files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end
end

%% Get the data (loop over all datasets)
refLoadTime = tic;
if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end
for kk = 1:MRSCont.nDatasets(1)
     for ll = 1: 1:MRSCont.nDatasets(2)
        [~] = printLog('OspreyLoad',kk,ll,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);   
        if ~(MRSCont.flags.didLoad == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'raw') && (kk > length(MRSCont.raw))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)

            % Read in the raw metabolite data. Since the Philips SDAT loader needs
            % to know the number of sub-spectra (e.g. from spectral editing), the
            % type of sequence needs to be differentiated here already.
            metab_ll = MRSCont.opts.MultipleSpectra.metab(ll);
            if MRSCont.flags.isUnEdited
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},1,MRSCont.flags.isSERIES);
                raw.flags.isUnEdited = 1;
            elseif MRSCont.flags.isMEGA
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},2,MRSCont.flags.isSERIES);
                raw.flags.isMEGA = 1;
            elseif MRSCont.flags.isHERMES
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},4,MRSCont.flags.isSERIES);
                raw.flags.isHERMES = 1;
            elseif MRSCont.flags.isHERCULES
                raw         = io_loadspec_sdat(MRSCont.files{metab_ll,kk},4,MRSCont.flags.isSERIES);
                raw.flags.isHERCULES = 1;
            end
            % Add NIfTI-MRS information
            raw                           = osp_add_nii_mrs_field(raw,MRSCont.ver.Osp);
            MRSCont.raw{metab_ll,kk}      = raw;

            % Read in the raw MM data. re_mm
            if MRSCont.flags.hasMM %re_mm
                temp_ll = MRSCont.opts.MultipleSpectra.mm(ll);
                if MRSCont.flags.isUnEdited %re_mm                    
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
                    [raw_mm] = op_rmempty(raw_mm); %re_mm
                    raw_mm.flags.isUnEdited = 1;
                elseif MRSCont.flags.isMEGA %re_mm
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},2,MRSCont.flags.isSERIES); %re_mm
                    raw_mm.flags.isMEGA = 1;
                elseif MRSCont.flags.isHERMES%re_mm
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
                    raw_mm.flags.isHERMES = 1;
                elseif MRSCont.flags.isHERCULES %re_mm
                    raw_mm = io_loadspec_sdat(MRSCont.files_mm{temp_ll,kk},1,MRSCont.flags.isSERIES); %re_mm
                    raw_mm.flags.isHERCULES = 1;
                end
                % Add NIfTI-MRS information
                raw_mm                      = osp_add_nii_mrs_field(raw_mm,MRSCont.ver.Osp);
                MRSCont.raw_mm{temp_ll,kk}  = raw_mm;
            end %re_mm      

            % Read in the raw reference data.
            if MRSCont.flags.hasRef
                ref_ll = MRSCont.opts.MultipleSpectra.ref(ll);
                if MRSCont.flags.isUnEdited                    
                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isUnEdited = 1;
                elseif MRSCont.flags.isMEGA
                    try % GO 03042024: this works for the JHU patch only but throws an error for product MEGA
                        raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},2,MRSCont.flags.isSERIES);
                    catch % GO 03042024: this works for product MEGA
                        raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    end
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isMEGA = 1;
                elseif MRSCont.flags.isHERMES
                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isHERMES = 1;
                 elseif MRSCont.flags.isHERCULES
                    raw_ref = io_loadspec_sdat(MRSCont.files_ref{ref_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    raw_ref.flags.isHERCULES = 1;
                end
                % Add NIfTI-MRS information
                raw_ref                     = osp_add_nii_mrs_field(raw_ref,MRSCont.ver.Osp);
                MRSCont.raw_ref{ref_ll,kk}  = raw_ref;
            end
            if MRSCont.flags.hasWater
                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
                raw_w   = io_loadspec_sdat(MRSCont.files_w{w_ll,kk},1,MRSCont.flags.isSERIES);
                raw_w = op_combine_water_subspecs(raw_w,0);
                raw_w.flags.isUnEdited = 1;
                % Add NIfTI-MRS information
                raw_w                     = osp_add_nii_mrs_field(raw_w,MRSCont.ver.Osp);
                MRSCont.raw_w{w_ll,kk}    = raw_w;
            end

            % Read in the MM reference data.
            if MRSCont.flags.hasMMRef
                temp_ll = MRSCont.opts.MultipleSpectra.mm_ref(ll);
                if MRSCont.flags.isUnEdited
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isUnEdited = 1;
                elseif MRSCont.flags.isMEGA
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},2,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isMEGA = 1;
                elseif MRSCont.flags.isHERMES
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isHERMES = 1;
                 elseif MRSCont.flags.isHERCULES
                    raw_mm_ref = io_loadspec_sdat(MRSCont.files_mm_ref{temp_ll,kk},1,MRSCont.flags.isSERIES);
                    raw_mm_ref = op_combine_water_subspecs(raw_mm_ref,0);
                    raw_mm_ref.flags.isHERCULES = 1;
                end
                % Add NIfTI-MRS information
                raw_mm_ref                      = osp_add_nii_mrs_field(raw_mm_ref,MRSCont.ver.Osp);
                MRSCont.raw_mm_ref{temp_ll,kk}  = raw_mm_ref;
            end
        end
    end
end
time = toc(refLoadTime);
[~] = printLog('done',time,MRSCont.nDatasets(1),MRSCont.nDatasets(2),progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI); 
% Set flag
MRSCont.flags.coilsCombined     = 1;
MRSCont.runtime.Load = time;
end

function [varargout] = osp_editSubSpecAlignLNorm(varargin)
%% [varargout] = osp_editSubSpecAlign(varargin)
%   Aligns sub-spectra of edited MRS data to minimize
%   subtraction artefacts. It uses a L1 Norm minimization including the
%   whole frequency range (Cleve et al., JMR, 2017 (https://doi.org/10.1016/j.jmr.2017.04.004) .
%
%   USAGE:
%       [outA, outB] = osp_editSubSpecAlign(inA, inB/target);
%
%   INPUTS:
%       inA        = Input data structure A.
%       inB        = Input data structure B. (optional)
%
%   OUTPUTS:
%       outA       = Output following alignment of averages.
%       outB       = Output following alignment of averages. (optional)
%
%   AUTHOR:
%       Dr. Helge Zollner (Johns Hopkins University, 2021-03-01)
%       hzoelln2@jhmi.edu
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2021-01-01: First version of the code.

% Determine whether there are 2 (MEGA) or 4 (HERMES/HERCULES) inputs
if nargin == 2 && isstruct(varargin{2})
    seqType = 'MEGA';
    inA     = varargin{1};
    inB     = varargin{2};
    if inA.subspecs > 1 || inB.subspecs > 1
        error('Error in osp_editSubSpecAlign! Both data structs must have only 1 sub-spectrum');
    end
elseif nargin == 2 && ~isstruct(varargin{2})
    in     = varargin{1};
    seqType = varargin{2};
    if in.subspecs == 1
        error('Error in osp_editSubSpecAlign! The data struct must have > 1 sub-spectrum');
    end
    switch seqType
        case 'MEGA'
            inA=op_takesubspec(in,1);
            inB=op_takesubspec(in,2);
        case 'HERMES'
            inA=op_takesubspec(in,1);
            inB=op_takesubspec(in,2);
            inC=op_takesubspec(in,3);
            inD=op_takesubspec(in,4);
        case 'HERCULES'
            inA=op_takesubspec(in,1);
            inB=op_takesubspec(in,2);
            inC=op_takesubspec(in,3);
            inD=op_takesubspec(in,4);
    end
else
    error('Error in osp_editSubSpecAlign! Needs to have either 2 spectra to align or one spectrum with sub-spectra and sequence type');
end

% Check whether data is coil-combined. If not, throw error.
if ~in.flags.addedrcvrs
    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
end

% Check whether data is averaged. If not, throw error.
if ~in.flags.averaged
    error('ERROR:  I think it only makes sense to do this after averaging using op_averaging.  ABORTING!!');
end




%%% 1. SET UP REQUIRED VARIABLES %%%
% Define the frequency ranges over which water, NAA, and Cho subtraction artefacts
% are to be minimized. Also, get a good starting estimate for the frequency
% alignment shift by determining the difference between the two maxima in
% the respective peak range (water, NAA, or Cho).
freq = inA.ppm;
freqLim(1,:) = freq <= 4 & freq >= 1.95;
x0(1,:) = [0 0];


% Optimization options
lsqnonlinopts = optimoptions(@lsqnonlin);
lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');

% Initialize common variables
t           = inA.t;


%%% 2. PERFORM ALIGNMENT BASED ON SEQUENCE TYPE
if strcmp(seqType, 'HERMES') || strcmp(seqType, 'HERCULES')


    a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
    fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
    param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
    % Apply the calculated frequency/phase adjustment to the inB spectrum
    fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
    specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
    % Create output
    outA = inA;
    outB = inB;
    outB.fids = fidsB;
    outB.specs = specsB;

    a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
    fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(1,:), t, x);
    param(2,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
    % Apply the calculated frequency/phase adjustment to the inC spectrum
    fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
    specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
    % Create output
    outC = inC;
    outC.fids = fidsC;
    outC.specs = specsC;

    a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
    fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(1,:), t, x);
    param(3,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
    % Apply the calculated frequency/phase adjustment to the inD spectrum
    fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
    specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);

    % Create output
    outD = inD;
    outD.fids = fidsD;
    outD.specs = specsD;

    % Create output
    merged = op_mergesubspec(outA,outB,outC,outD);

    % Add NIfTI-MRS provenance
    % Generate fields for provenance
    fields.Method   = 'Aligment of subtraction sub-spectra';
    fields.Details  = ['L1 norm optimization of HADAMARD spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
    merged = op_add_analysis_provenance(merged,fields);

    varargout{1} = merged;

elseif strcmp(seqType, 'MEGA')
    % For MEGA-edited data, the 'reporter signal' that is used to align the
    % two sub-spectra will depend on the edited metabolite. Since the peak
    % needs to be identical in both acquisitions, we choose the residual
    % water peak for GABA-edited data, and the NAA peak for GSH-edited
    % data.

    a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
    fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
    param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);

    % Apply the calculated frequency/phase adjustment to the inB spectrum
    fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
    specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);

    % Create output
    outA = inA;
    outB = inB;
    outB.fids = fidsB;
    outB.specs = specsB;
    if isstruct(varargin{2}) 
        % Add NIfTI-MRS provenance
        % Generate fields for provenance
        fields.Method   = 'Aligment of subtraction sub-spectra';
        fields.Details  = ['L1 norm optimization of ON/OFF spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
        outA = op_add_analysis_provenance(outA,fields);

        fields.Method   = 'Aligment of subtraction sub-spectra';
        fields.Details  = ['L1 norm optimization of ON/OFF spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
        outB = op_add_analysis_provenance(outB,fields);

        varargout{1} = outA;
        varargout{2} = outB;
    else
        merged = op_mergesubspec(outA,outB);

        % Add NIfTI-MRS provenance
        % Generate fields for provenance
        fields.Method   = 'Aligment of subtraction sub-spectra';
        fields.Details  = ['L1 norm optimization of ON/OFF spectra (Cleve et al. 2017), dim = DIM_EDIT, frequency range (' num2str(1.95) ',' num2str(4) ') ppm'];
        merged = op_add_analysis_provenance(merged,fields);

        varargout{1} = merged;
    end

end

end

function out = objFunc(in1, in2, freqLim, t, x)

% This is the objective function that minimizes the absolute sum of the difference over the 
% frequency range (freqLim) between the target spectrum (in1) and the 
% spectrum that is to be frequency-and-phase aligned (in2).

f   = x(1); % frequency correction
phi = x(2); % phase correction

y1 = in1.fids;
y2 = in2.fids .* exp(1i*pi*(t'*f*2+phi/180)); % apply to time-domain data

% fft
a = real(fftshift(fft(y1,[],1),1));
b = real(fftshift(fft(y2,[],1),1));

% return difference vector over defined frequency range
DIFF = a - b;
out = sum(abs(DIFF(freqLim)));

end

function [out] = osp_editSubSpecAlign(varargin)
%% [varargout] = osp_editSubSpecAlign(varargin)
%   Aligns sub-spectra of (multiplexed) edited MRS data to minimize
%   subtraction artefacts.
%
%   USAGE:
%       [outA, outB, outC, outD] = osp_editSubSpecAlign(in, seq, target,unstableWater);
%
%   INPUTS:
%       in        = Input data structure with sub-spectrum A.
%       seq       = sequence type
%       target     = String. Can be 'GABA' or 'GSH'. (necessary if only two
%                    inputs inA and inB are provided)
%       unstableWater = Flag for unstable residual water. This ignores
%                       water for the optimization and uses Choline instead
%
%   OUTPUTS:
%       outA       = Output following alignment of averages.
%       outB       = Output following alignment of averages.
%       outC       = Output following alignment of averages. (optional)
%       outD       = Output following alignment of averages. (optional)
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-08-15)
%       goeltzs1@jhmi.edu
%       Dr. Mark Mikkelsen (Johns Hopkins University)
%       mmikkel5@jhmi.edu
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-08-15: First version of the code.


% Determine whether there are 2 (MEGA) or 4 (HERMES/HERCULES) inputs
if nargin == 5
    in     = varargin{1};
    seqType = varargin{2};
    target1 = varargin{3};
    target2 = varargin{4};
    unstableWater = varargin{5};
elseif nargin == 4 && (strcmp(varargin{2},'HERMES') || strcmp(varargin{2},'HERCULES'))
    in     = varargin{1};
    seqType = varargin{2};
    target1 = varargin{3};
    target2 = varargin{4};
    unstableWater = 0;
elseif nargin == 4
    in     = varargin{1};
    seqType = varargin{2};
    target = varargin{3};
    unstableWater = varargin{4};
elseif nargin == 3 && strcmp(varargin{2},'MEGA')
    in     = varargin{1};
    seqType = varargin{2};
    target  = varargin{3};
    unstableWater = 0;
else
    error('Error in osp_editSubSpecAlign! For provide raw data struct, the sequence type, the name of the editing target, and the optional unstable water flag.')
end

% Check whether data is coil-combined. If not, throw error.
if ~in.flags.addedrcvrs
    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
end

% Check whether data is averaged. If not, throw error.
if ~in.flags.averaged
    error('ERROR:  I think it only makes sense to do this after averaging using op_averaging.  ABORTING!!');
end

switch seqType
   case 'MEGA'
        inA=op_takesubspec(in,1);
        inB=op_takesubspec(in,2);
    case 'HERMES'
        inA=op_takesubspec(in,1);
        inB=op_takesubspec(in,2);
        inC=op_takesubspec(in,3);
        inD=op_takesubspec(in,4);
    case 'HERCULES'
        inA=op_takesubspec(in,1);
        inB=op_takesubspec(in,2);
        inC=op_takesubspec(in,3);
        inD=op_takesubspec(in,4);
end


%%% 1. SET UP REQUIRED VARIABLES %%%
% Define the frequency ranges over which water, NAA, and Cho subtraction artefacts
% are to be minimized. Also, get a good starting estimate for the frequency
% alignment shift by determining the difference between the two maxima in
% the respective peak range (water, NAA, or Cho).
freq = inA.ppm;
% Water
freqLim(1,:) = freq <= 4.68+0.22 & freq >= 4.68-0.22;
[~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
freq2 = freq(freqLim(1,:));
maxFreq = freq2(i);
for jj = 1:2
    tmp(jj,:) = freq <= maxFreq(jj)+0.22 & freq >= maxFreq(jj)-0.22;
end
freqLim(1,:) = or(tmp(1,:), tmp(2,:));
f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
x0(1,:) = [f0 0];

% NAA
freqLim(2,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
peaks = '2.01 ppm (A/B)';
switch seqType
    case 'HERCULES'
        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
    case 'HERMES'
        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
    case 'MEGA'
        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inB.specs(freqLim(2,:))))]);
end
freq2 = freq(freqLim(2,:));
maxFreq = freq2(i);
for jj = 1:2
    tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
end
freqLim(2,:) = or(tmp(1,:), tmp(2,:));
f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
x0(2,:) = [f0 0];

% In case the water peak is not well-behaved and has several peaks we are
% possibly detecting several peaks. This will lead to unreasonable shifts
% between the sub-spectra. In this case, we use the Choline peak.
if unstableWater

    freqLim(1,:) = freq <= 3.22+0.09 & freq >= 3.22-0.09;
    [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
    freq2 = freq(freqLim(1,:));
    maxFreq = freq2(i);
    for jj = 1:2
        tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
    end
    freqLim(1,:) = or(tmp(1,:), tmp(2,:));
    f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
    x0(1,:) = [f0 0];

end

% Optimization options
lsqnonlinopts = optimoptions(@lsqnonlin);
lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');

% Initialize common variables
t           = inA.t;


%%% 2. PERFORM ALIGNMENT BASED ON SEQUENCE TYPE
if strcmp(seqType, 'HERMES') || strcmp(seqType, 'HERCULES') 
    if ~(exist('target1','var') && exist('target2','var'))
        %Fall back into default HERMES GABA GSH editing
        target1 = 'GABA';
        target2 = 'GSH';
    end

    target = [target1 target2];
    switch target
        case {'GABAGSH','GABALac','GABAEtOH'}  
            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
            % minimize the residual water peak in the difference between them.

            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inB spectrum
            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
            % Create output
            outA = inA;
            outB = inB;
            outB.fids = fidsB;
            outB.specs = specsB;

            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
            % in the difference between them.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(2,:), t, x);
            param(2,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inC spectrum
            fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
            specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
            % Create output
            outC = inC;
            outC.fids = fidsC;
            outC.specs = specsC;

            % Then, align the GABA-ON-GSH-ON spectra to the **corrected** GABA-OFF-GSH-ON
            % spectrum - this is something Mark/Georg independently from each other
            % found out to work best for HERMES/HERCULES data.

            % Find Cho peak and get starting estimate for the frequency shift
            freqLim(3,:) = freq <= 3.2+0.09 & freq >= 3.2-0.09;
            [~,i] = max([abs(real(outC.specs(freqLim(3,:)))) abs(real(inD.specs(freqLim(3,:))))]);
            freq2 = freq(freqLim(3,:));
            maxFreq = freq2(i);
            for jj = 1:2
                tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
            end
            freqLim(3,:) = or(tmp(1,:), tmp(2,:));
            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
            x0(3,:) = [f0 0];

            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
            fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(3,:), t, x);
            param(3,:) = lsqnonlin(fun, x0(3,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inD spectrum
            fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
            specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);

            % Create output
            outD = inD;
            outD.fids = fidsD;
            outD.specs = specsD;

        case 'NAANAAG' 
            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
            % minimize the residual water peak in the difference between them.
            % NAA
            freqLim(1,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
            [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
            freq2 = freq(freqLim(1,:));
            maxFreq = freq2(i);
            for jj = 1:2
                tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
            end
            freqLim(1,:) = or(tmp(1,:), tmp(2,:));
            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
            x0(1,:) = [f0 0];
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inB spectrum
            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
            % Create output
            outA = inA;
            outB = inB;
            outB.fids = fidsB;
            outB.specs = specsB;

            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
            % in the difference between them.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(2,:), t, x);
            param(2,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inC spectrum
            fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
            specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
            % Create output
            outC = inC;
            outC.fids = fidsC;
            outC.specs = specsC;

            % Then, align the GABA-ON-GSH-ON spectra to the **corrected** GABA-OFF-GSH-ON
            % spectrum - this is something Mark/Georg independently from each other
            % found out to work best for HERMES/HERCULES data.

            % Find Cho peak and get starting estimate for the frequency shift
            freqLim(3,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
            [~,i] = max([abs(real(outC.specs(freqLim(3,:)))) abs(real(inD.specs(freqLim(3,:))))]);
            freq2 = freq(freqLim(3,:));
            maxFreq = freq2(i);
            for jj = 1:2
                tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
            end
            freqLim(3,:) = or(tmp(1,:), tmp(2,:));
            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
            x0(3,:) = [f0 0];

            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
            fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(3,:), t, x);
            param(3,:) = lsqnonlin(fun, x0(3,:), [], [], lsqnonlinopts);
            % Apply the calculated frequency/phase adjustment to the inD spectrum
            fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
            specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);

            % Create output
            outD = inD;
            outD.fids = fidsD;
            outD.specs = specsD;
    end
    % Create output
    out = op_mergesubspec(outA,outB,outC,outD);

    % Add NIfTI-MRS provenance
    % Generate fields for provenance
    if unstableWater
       peaks = '3.2 ppm (A/B), 2.01 ppm (B/C), 3.2 (C/D)';
    else
       peaks = '4.68 ppm (A/B), 2.01 ppm (B/C), 3.2 (C/D)';
    end
    fields.Method   = 'Aligment of subtraction sub-spectra';
    fields.Details  = ['L2 optimization of HADAMARD spectra (Mikkelsen et al. 2018), dim = DIM_EDIT, reference = ' peaks];
    out = op_add_analysis_provenance(out,fields);

elseif strcmp(seqType, 'MEGA')
    % For MEGA-edited data, the 'reporter signal' that is used to align the
    % two sub-spectra will depend on the edited metabolite. Since the peak
    % needs to be identical in both acquisitions, we choose the residual
    % water peak for GABA-edited data, and the NAA peak for GSH-edited
    % data.
    switch target
        case 'GABA'
            % For GABA-edited data, align the GABA-ON spectrum using the
            % residual water peak.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
            peaks = '4.7 ppm (A/B)';

        case 'GSH'
            % For GSH-edited data, align the GSH-ON spectrum using the
            % NAA peak.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);

        case 'Lac'
            % For Lac-edited data, align the Lac-ON spectrum using the
            % NAA peak.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);

        case 'PE322'
            % For Lac-edited data, align the Lac-ON spectrum using the
            % NAA peak.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);

        case 'PE398'
            % For Lac-edited data, align the Lac-ON spectrum using the
            % NAA peak.
            % Determine normalization factor so that normalized spectra are entered
            % into the optimization
            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(2,:), t, x);
            param(1,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);


        otherwise
            error('Error in osp_editSubSpecAlign! Target string not recognized.');
    end

    % Apply the calculated frequency/phase adjustment to the inB spectrum
    fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
    specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);

    % Create output
    outA = inA;
    outB = inB;
    outB.fids = fidsB;
    outB.specs = specsB;
    out=op_mergesubspec(outA,outB);

    % Add NIfTI-MRS provenance
    % Generate fields for provenance
    if unstableWater
       peaks = '3.68 ppm (A/B)';
    end
    fields.Method   = 'Aligment of subtraction sub-spectra';
    fields.Details  = ['L2 optimization of ON/OFF spectra (Mikkelsen et al. 2018), dim = DIM_EDIT, reference = ' peaks];
    out = op_add_analysis_provenance(out,fields);

    varargout{1} = out;

end

end


function out = objFunc(in1, in2, freqLim, t, x)

% This is the objective function that minimizes the difference over the 
% frequency range (freqLim) between the target spectrum (in1) and the 
% spectrum that is to be frequency-and-phase aligned (in2).

f   = x(1); % frequency correction
phi = x(2); % phase correction

y1 = in1.fids;
y2 = in2.fids .* exp(1i*pi*(t'*f*2+phi/180)); % apply to time-domain data

% fft
a = real(fftshift(fft(y1,[],1),1));
b = real(fftshift(fft(y2,[],1),1));

% return difference vector over defined frequency range
DIFF = a - b;
out = DIFF(freqLim);

end

% op_combinesubspecs.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_combinesubspecs(in,mode);
% 
% DESCRIPTION:
% Combine the subspectra in an acquisition either by addition or
% subtraction.
% 
% INPUTS:
% in        = input data in matlab structure format.
% mode      = -"diff" adds the subspectra together (this is counter intuitive,
%             but the reason is that many "difference editing" sequences use phase
%             cycling of the readout ADC to achieve "subtraction by addition".
%             -"summ" performs a subtraction of the subspectra.
%
% OUTPUTS:
% out       = Output following combination of subspectra.  

function out=op_combinesubspecs(in,mode);

if in.flags.subtracted
    error('ERROR:  Subspectra have already been combined!  Aborting!');
end
if in.flags.isFourSteps
    error('ERROR: data with four steps must first be converted using op_fourStepCombine.m!  Aborting!');
end

% if ~in.flags.freqcorrected
%     disp('WARNING:  Frequency correction has not yet been performed!');
% end
% if ~in.flags.phasecorrected
%     disp('WARNING:  Phase correction has not yet been performed!');
% end


if mode=='diff'
    %add the spectrum along the subSpecs dimension;
    fids=sum(in.fids,in.dims.subSpecs);
    fids=fids/in.sz(in.dims.subSpecs); %divide by number of subspecs so that this is an averaging operation;
elseif mode=='summ'
    %subtract the spectrum along the subSpecs dimension;
    fids=diff(in.fids,1,in.dims.subSpecs);
    fids=fids/in.sz(in.dims.subSpecs); %divide by nymber of subspecs so that this is an averaging operation;
end

fids=squeeze(fids);

%re-calculate Specs using fft
specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

%change the dims variables
if in.dims.t>in.dims.subSpecs
    dims.t=in.dims.t-1;
else
    dims.t=in.dims.t;
end
if in.dims.coils>in.dims.subSpecs
    dims.coils=in.dims.coils-1;
else
    dims.coils=in.dims.coils;
end
if in.dims.averages>in.dims.subSpecs
    dims.averages=in.dims.averages-1;
else
    dims.averages=in.dims.averages;
end
dims.subSpecs=0;
if in.dims.extras>in.dims.subSpecs
    dims.extras=in.dims.extras-1;
else
    dims.extras=in.dims.extras;
end

%re-calculate the sz variable
sz=size(fids);


%FILLING IN DATA STRUCTURE
out=in;
out.fids=fids;
out.specs=specs;
out.sz=sz;
out.dims=dims;
out.subspecs=1;
out.averages=in.averages/2;

%FILLING IN THE FLAGS
out.flags=in.flags;
out.flags.writtentostruct=1;
out.flags.subtracted=1;

function [out] = op_combine_water_subspecs(in,average)
% Some formats end up having subspectra in their reference scans
% (e.g. Philips), as well as empty lines. Intercept these cases
% here.
if nargin < 2
    average = 1;
end
    out = in;
    if out.subspecs == 2
        raw_A               = op_takesubspec(out,1);
        [raw_A]             = op_rmempty(raw_A);            % Remove empty lines
        raw_B               = op_takesubspec(out,2);
        [raw_B]             = op_rmempty(raw_B);            % Remove empty lines
        out                 = op_concatAverages(raw_A,raw_B);
    end

    if out.subspecs == 4
        raw_A               = op_takesubspec(out,1);
        [raw_A]             = op_rmempty(raw_A);            % Remove empty lines
        raw_B               = op_takesubspec(out,2);
        [raw_B]             = op_rmempty(raw_B);            % Remove empty lines
        raw_C               = op_takesubspec(out,3);
        [raw_C]             = op_rmempty(raw_C);            % Remove empty lines
        raw_D               = op_takesubspec(out,4);
        [raw_D]             = op_rmempty(raw_D);            % Remove empty lines
        out                 = op_concatAverages(op_concatAverages(raw_A,raw_B),op_concatAverages(raw_C,raw_D));
    end
    if out.subspecs == 1
        [out]             = op_rmempty(out);            % Remove empty lines
    end
    if average
        % Align and verage the refernce data
        if out.averages > 1 && ~out.flags.averaged
            [out]             = op_rmempty(out);
            [out,~,~]               = op_alignAverages(out, 1, 'n');
            out                     = op_averaging(out);            % Average
        else
            out.flags.averaged  = 1;
            out.dims.averages   = 0;
        end
    end
    out.names = {'A'};
end

% op_addScans.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_addScans(in1,in2,subtract);
% 
% DESCRIPTION:
% Add or subtract two scans together.
% 
% INPUTS:
% in1        = First spectrum to add (in matlab structure format)
% in2        = Second spectrum to add (also in matlab structure format).
% subtract	 = (optional).  Add or subtract?  (0 = add, 1=subtract).
%             Default=0;
%
% OUTPUTS:
% out        = Result of adding inputs in1 and in2.  


function out=op_addScans(in1,in2,subtract);

if nargin<3
    subtract=0;
end

%If in1 is an empty structure (in1=struct()), then the output is just in2.  
%This functionality is useful for looping, when you are starting from zero 
%and adding many spectra together.  JN 17/05/2013.
if isempty(fieldnames(in1))
    if subtract==1
        fids=-in2.fids;
    else
        fids=in2.fids;
    end

    %re-calculate Specs using fft
    specs=fftshift(fft(fids,[],in2.dims.t),in2.dims.t);

    %FILLING IN DATA STRUCTURES
    out=in2;
    out.fids=fids;
    out.specs=specs;

    %FILLING IN THE FLAGS
    out.flags=in2.flags;


else
    if subtract
        fids=in1.fids-in2.fids;
    else
        fids=in1.fids+in2.fids;
    end

    if in1.sz ~= in2.sz
        error('ERROR:  Spectra must be the same number of points');
    end
    if in1.dwelltime ~= in2.dwelltime
        error('ERROR:  Spectra must have the same dwelltime');
    end
    if in1.spectralwidth ~= in2.spectralwidth
        error('ERROR:  Spectra must have the same spectral width');
    end

    %re-calculate Specs using fft
    specs=fftshift(fft(fids,[],in1.dims.t),in1.dims.t);

    %FILLING IN DATA STRUCTURES
    out=in1;
    out.fids=fids;
    out.specs=specs;

    %FILLING IN THE FLAGS
    out.flags=in1.flags;
end

function [MRSCont] = OspreyProcess(MRSCont)
%% [MRSCont] = OspreyProcess(MRSCont)
%   This function pre-processes MRS data from all major vendors.
%   Data is read from the provided input filenames. It is shaped,
%   preprocessed, aligned, etc. according to the type of sequence
%   (un-edited data, MEGA-edited (ON/OFF), HERMES/HERCULES (A/B/C/D),
%   etc.).
%
%   USAGE:
%       MRSCont = OspreyProcess(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-19)
%       goeltzs1@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-02-19: First version of the code.

outputFolder = MRSCont.outputFolder;
diary(fullfile(outputFolder, 'LogFile.txt'));

% Checking for version, toolbox, and previously run modules
[~,MRSCont.ver.CheckOsp ] = osp_CheckRunPreviousModule(MRSCont, 'OspreyProcess');


%% Data post-processing starts here
warning('off','all');

% Loop over all datasets
refProcessTime = tic;
if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end

for kk = 1:MRSCont.nDatasets(1) %Subject loop
    for ll = 1: 1:MRSCont.nDatasets(2) %Experiment loop
        [~] = printLog('OspreyProcess',kk,ll,MRSCont.nDatasets(1),progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);


        if ~(MRSCont.flags.didProcess == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'processed') && (kk > size(MRSCont.processed.metab,2)))  || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
            metab_ll = MRSCont.opts.MultipleSpectra.metab(ll);
%%          %%% 1. GET RAW DATA %%%
            raw                         = MRSCont.raw{metab_ll,kk};                                          % Get the kk-th dataset

            % Get sequence type set up
            if raw.flags.isUnEdited
                seq = 'unedited';
            elseif raw.flags.isMEGA
                seq = 'MEGA';
            elseif raw.flags.isHERMES
                seq = 'HERMES';
            elseif raw.flags.isHERCULES
                seq = 'HERCULES';
            end

%%          %%% 1B. GET MM DATA %%%
            if MRSCont.flags.hasMM
                mm_ll = MRSCont.opts.MultipleSpectra.mm(ll);
                raw_mm                         = MRSCont.raw_mm{mm_ll,kk};              % Get the kk-th dataset re_mm
                if raw_mm.averages > 1 && raw_mm.flags.averaged == 0 %re_mm
                    [raw_mm,fs,phs]               = op_alignAverages(raw_mm, 1, 'n'); %re_mm
                    raw_mm                     = op_averaging(raw_mm);            % Average re_mm
                else %re_mm
                    raw_mm.flags.averaged  = 1; %re_mm
                    raw_mm.dims.averages   = 0; %re_mm
                    fs = 0;
                    phs = 0;
                end
                if raw_mm.flags.isUnEdited
                    [raw_mm,~]                     = op_ppmref(raw_mm,4.6,4.8,4.68);  % Reference to water @ 4.68 ppm  %re_mm
                end
                if raw_mm.flags.isUnEdited
                    raw_mm.names = {'A'};
                    raw_mm.target = {''};
                    raw_mm.specReg{1}.fs              = fs; % save align parameters
                    raw_mm.specReg{1}.phs             = phs; % save align parameters
                    raw_mm.specReg{1}.weights{1}         = ones(size(phs)); % save align parameters
                    driftPre = 0;
                end
                if raw_mm.flags.isMEGA
                    raw_mm.names = {'A','B'};
                    raw_mm.target = MRSCont.opts.editTarget';
                    raw_mm.specReg{1}.fs              = fs; % save align parameters
                    raw_mm.specReg{1}.phs             = phs; % save align parameters
                    raw_mm.specReg{1}.weights{1}         = ones(size(phs)); % save align parameters
                    raw_mm.specReg{1}.weights{2}         = ones(size(phs)); % save align parameters
                    driftPre{1} = 0;
                    driftPre{2} = 0;
                end
                if raw_mm.flags.isHERMES || raw_mm.flags.isHERCULES
                    raw_mm.names = {'A', 'B', 'C', 'D'};
                    raw_mm.target = MRSCont.opts.editTarget';
                    raw_mm.specReg{1}.fs              = fs; % save align parameters
                    raw_mm.specReg{1}.phs             = phs; % save align parameters
                    raw_mm.specReg{1}.weights{1}         = size(phs); % save align parameters
                    raw_mm.specReg{1}.weights{2}         = size(phs); % save align parameters
                    raw_mm.specReg{1}.weights{3}         = size(phs); % save align parameters
                    raw_mm.specReg{1}.weights{4}         = size(phs); % save align parameters
                    driftPre{1} = 0;
                    driftPre{2} = 0;
                    driftPre{3} = 0;
                    driftPre{4} = 0;
                end
            end  %re_mm

%%          %%% 1C. GET MM REFERENCE DATA %%%
            if MRSCont.flags.hasMMRef
                mm_ref_ll = MRSCont.opts.MultipleSpectra.mm_ref(ll);
                raw_mm_ref = MRSCont.raw_mm_ref{mm_ref_ll,kk};              % Get the kk-th dataset
                raw_mm_ref = op_combine_water_subspecs(raw_mm_ref);
            end

%%          %%% 1D. GET REFERENCE DATA %%%
            if MRSCont.flags.hasRef
                ref_ll = MRSCont.opts.MultipleSpectra.ref(ll);
                raw_ref = MRSCont.raw_ref{ref_ll,kk};              % Get the kk-th dataset

                % Combine SPECIAL sub-spectra
                if MRSCont.flags.isSPECIAL
                    raw_ref = combine_special_subspecs(raw_ref);
                end

                if raw_ref.averages > 1 && raw_ref.flags.averaged == 0
                    [raw_ref,fs,phs]                 = op_alignAverages(raw_ref, 1, 'n');
                    badAverages=find(abs(fs)>6);
                    goodAverages=find(abs(fs)<6); 
                    if ~isempty(badAverages)
                        fs(badAverages) =[];
                        phs(badAverages) =[];
                        raw_ref.AveragesToKeep = goodAverages;
                        raw_ref.fids=raw_ref.fids(:,goodAverages,:,:);
                        raw_ref.specs=fftshift(ifft(raw_ref.fids,[],raw_ref.dims.t),raw_ref.dims.t);
                        raw_ref.sz=size(raw_ref.fids);
                        raw_ref.averages=length(goodAverages);
                    end
                    raw_ref                       = op_averaging(raw_ref);              % Average
                    raw_ref.specReg{1}.fs              = fs; % save align parameters
                    raw_ref.specReg{1}.phs             = phs; % save align parameters
                else
                    raw_ref.flags.averaged    = 1;
                    raw_ref.dims.averages     = 0;
                end

                raw_ref = op_combine_water_subspecs(raw_ref);                
            end

%%           %%% 1E. GET SHORT-TE WATER DATA %%%
             % And do the processing
             if MRSCont.flags.hasWater
                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
                raw_w                           = MRSCont.raw_w{w_ll,kk};                % Get the kk-th dataset

                % Combine SPECIAL sub-spectra
                if MRSCont.flags.isSPECIAL
                    raw_w = combine_special_subspecs(raw_w);
                end

                if raw_w.averages > 1 && raw_w.flags.averaged == 0
                    [raw_w,fs,phs]                 = op_alignAverages(raw_w, 1, 'n');
                    badAverages=find(abs(fs)>6);
                    goodAverages=find(abs(fs)<6); 
                    if ~isempty(badAverages)
                        fs(badAverages) =[];
                        phs(badAverages) =[];
                        raw_w.AveragesToKeep = goodAverages;
                        raw_w.fids=raw_w.fids(:,goodAverages,:,:);
                        raw_w.specs=fftshift(ifft(raw_w.fids,[],raw_w.dims.t),raw_w.dims.t);
                        raw_w.sz=size(raw_w.fids);
                        raw_w.averages=length(goodAverages);
                    end
                    raw_w                       = op_averaging(raw_w);              % Average
                    raw_w.specReg{1}.fs              = fs; % save align parameters
                    raw_w.specReg{1}.phs             = phs; % save align parameters
                else
                    raw_w.flags.averaged    = 1;
                    raw_w.dims.averages     = 0;
                end

                if raw_w.subspecs > 1
                    raw_w = op_combine_water_subspecs(raw_w);
                end
                if ~MRSCont.flags.isMRSI
                    [raw_w,~]                       = op_eccKlose(raw_w, raw_w);        % Klose eddy current correction
                else
                    [raw_w,~]=op_autophase(raw_w,2,2*4.68);
                end
                [raw_w,~]                       = op_ppmref(raw_w,4.6,4.8,4.68);    % Reference to water @ 4.68 ppm
                raw_w.names = {'A'};
                MRSCont.processed.w{w_ll,kk}         = raw_w; % Save back to MRSCont container
            end

%%          %%% 2a. PHANTOM-SPECIFIC PRE-PROCESSING %%%
            % If this is phantom data (assuming room temperature), we want to
            % perform a few specific pre-processing steps.
            if MRSCont.flags.isPhantom
                % First, we undo phase cycling by dividing by the first data
                % point (this is mainly experimental at this point, but has
                % proved beneficial for phase-cycled GE data).
    %             for rr = 1:raw.rawAverages
    %                 phi = repelem(conj(raw.fids(1,rr))./abs(raw.fids(1,rr)),size(raw.fids,1));
    %                 raw.fids(:,rr) = raw.fids(:,rr) .* phi';
    %                 raw.specs = fftshift(fft(raw.fids,[],1));
    %             end

                % Next, shift the entire metabolite spectrum by 0.15 ppm.
                % This doesn't have to be completely accurate, since additional
                % referencing steps are performed in the later stages of
                % post-processing and modelling, but we want the prominent singlets
                % to appear within 0.1 ppm of their expected in-vivo positions.
                phantomShiftPPM = 0.15 * raw.txfrq*1e-6;
                raw = op_freqshift(raw, -phantomShiftPPM);

                % Finally, apply some linebroadening. High-quality in-vitro
                % data may have linewidth lower than the simulated basis set
                % data.
                raw = op_filter(raw, 2);
                if MRSCont.flags.hasRef
                    raw_ref = op_filter(raw_ref, 2);
                end
                if MRSCont.flags.hasWater
                    raw_w = op_filter(raw_w, 2);
                    MRSCont.processed.w{ll,kk}         = raw_w; % Save back to MRSCont container
                end
            end

%%          %%% 2b. COMBINING SPECIAL SUB-SPECTRA %%%
            if MRSCont.flags.isSPECIAL
                raw = combine_special_subspecs(raw);
            end

%%          %%% 3. FREQUENCY/PHASE CORRECTION AND AVERAGING %%%
            if raw.averages > 1 && raw.flags.averaged == 0
                % Calculate starting values for spectral registration
                 [refShift_ind_ini]=op_preref(raw,seq);
                % Perform robust spectral correction with weighted averaging.
                % This can obviously only be done, if the spectra have not been
                % pre-averaged, i.e. in some older RDA and DICOM files (which should,
                % generally, not be used).
                if ~MRSCont.flags.isPhantom
                    switch MRSCont.opts.SpecReg %Pick spectral registration method (default is Robust Spectral Registration)
                        case 'ProbSpecReg'
                            [raw, fs, phs, weights, driftPre, driftPost]   = op_probabSpecReg(raw, seq, 0,refShift_ind_ini);
                        case 'RobSpecReg'
                            [raw, fs, phs, weights, driftPre, driftPost]     = op_robustSpecReg(raw, seq, 0,refShift_ind_ini); % Align and average
                        case 'RestrSpecReg'
                            if isfield(MRSCont.opts,'SpecRegRange')
                                [raw, fs, phs, weights, driftPre, driftPost]     = op_SpecRegFreqRestrict(raw, seq, 0,refShift_ind_ini,0,MRSCont.opts.SpecRegRange(1),MRSCont.opts.SpecRegRange(2)); % Align and average
                            else
                                [raw, fs, phs, weights, driftPre, driftPost]     = op_SpecRegFreqRestrict(raw, seq, 0,refShift_ind_ini,0,MRSCont.opts.fit.range(1),MRSCont.opts.fit.range(2)); % Align and average
                            end
                        case 'none'
                            [raw, fs, phs, weights, driftPre, driftPost]     = op_SpecRegFreqRestrict(raw, seq, 0,refShift_ind_ini,1); % Align and average
                    end
                else
                    switch MRSCont.opts.SpecReg %Pick spectral registration method (default is Robust Spectral Registration)
                        case 'none'
                            [raw, fs, phs, weights, driftPre, driftPost]     = op_SpecRegFreqRestrict(raw, seq, 0,refShift_ind_ini,1); % Align and average
                        otherwise
                            [raw, fs, phs, weights, driftPre, driftPost]   = op_SpecRegFreqRestrict(raw, seq, 0,refShift_ind_ini,0,0.5,4.2);
                    end
                end

                raw.specReg{1}.fs              = fs; % save align parameters
                raw.specReg{1}.phs             = phs; % save align parameters
                if raw.flags.isUnEdited
                    raw.specReg{1}.weights         = weights; % save align parameters);
                    raw.specReg{1}.weights{1}         = raw.specReg{1}.weights{1}'/max(raw.specReg{1}.weights{1}(1,:));
                end
                if raw.flags.isMEGA
                    raw.specReg{1}.weights         = weights; % save align parameters);
                    raw.specReg{1}.weights{1} = raw.specReg{1}.weights{1}'/(max(raw.specReg{1}.weights{1}(1,:)));
                    raw.specReg{1}.weights{2} = raw.specReg{1}.weights{2}'/(max(raw.specReg{1}.weights{2}(1,:)));
                end
                if raw.flags.isHERMES || raw.flags.isHERCULES
                    raw.specReg{1}.weights         = weights; % save align parameters);
                    raw.specReg{1}.weights{1} = raw.specReg{1}.weights{1}'/(max(raw.specReg{1}.weights{1}(1,:)));
                    raw.specReg{1}.weights{2} = raw.specReg{1}.weights{2}'/(max(raw.specReg{1}.weights{2}(1,:)));
                    raw.specReg{1}.weights{3} = raw.specReg{1}.weights{3}'/(max(raw.specReg{1}.weights{3}(1,:)));
                    raw.specReg{1}.weights{4} = raw.specReg{1}.weights{4}'/(max(raw.specReg{1}.weights{4}(1,:)));
                end

            else
                % If there is still an average dimension, squeeze
                if raw.dims.averages > 0
                    raw.fids = squeeze(sum(raw.fids, raw.dims.averages));
                    raw.specs=fftshift(fft(raw.fids,[],raw.dims.t),raw.dims.t);
                    if raw.dims.t>raw.dims.averages
                        raw.dims.t=raw.dims.t-1;
                    else
                        raw.dims.t=raw.dims.t;
                    end
                    if raw.dims.coils>raw.dims.averages
                        raw.dims.coils=raw.dims.coils-1;
                    else
                        raw.dims.coils=raw.dims.coils;
                    end
                    raw.dims.averages=0;
                    if raw.dims.subSpecs>raw.dims.averages
                        raw.dims.subSpecs=raw.dims.subSpecs-1;
                    else
                        raw.dims.subSpecs=raw.dims.subSpecs;
                    end
                    if raw.dims.extras>raw.dims.averages
                        raw.dims.extras=raw.dims.extras-1;
                    else
                        raw.dims.extras=raw.dims.extras;
                    end
                end
                raw.sz=size(raw.fids);

                raw.flags.averaged  = 1;
                if raw.flags.isUnEdited
                    raw.specReg{1}.fs              = 0; % save align parameters
                    raw.specReg{1}.phs             = 0; % save align parameters
                    raw.specReg{1}.weights{1}         = 1; % save align parameters
                    driftPre = op_measureDrift(raw);
                end
                if raw.flags.isMEGA
                    raw.specReg{1}.fs              = zeros(1,2); % save align parameters
                    raw.specReg{1}.phs             = zeros(1,2); % save align parameters
                    raw.specReg{1}.weights{1}         = ones(1,1); % save align parameters
                    raw.specReg{1}.weights{2}         = ones(1,1); % save align parameters
                    driftPre{1} = 0;
                    driftPre{2} = 0;
                end
                if raw.flags.isHERMES || raw.flags.isHERCULES
                    raw.specReg{1}.fs              = zeros(1,4); % save align parameters
                    raw.specReg{1}.phs             = zeros(1,4); % save align parameters
                    raw.specReg{1}.weights{1}         = ones(1,1); % save align parameters
                    raw.specReg{1}.weights{2}         = ones(1,1); % save align parameters
                    raw.specReg{1}.weights{3}         = ones(1,1); % save align parameters
                    raw.specReg{1}.weights{4}         = ones(1,1); % save align parameters
                    driftPre{1} = 0;
                    driftPre{2} = 0;
                    driftPre{3} = 0;
                    driftPre{4} = 0;
                end
                driftPost = driftPre;
            end

%%          %%% 4. GET REFERENCE DATA / EDDY CURRENT CORRECTION %%%
            % If there are reference scans, load them here to allow eddy-current
            % correction of the raw data.
            if MRSCont.flags.hasRef
                if MRSCont.flags.hasMM
                    if MRSCont.flags.hasMMRef
                        if MRSCont.opts.ECC.mm(mm_ref_ll,kk)
                            [raw_mm,raw_mm_ref]                   = op_eccKlose(raw_mm, raw_mm_ref);        % Klose eddy current correction
                        else
                            [~,raw_mm_ref]                   = op_eccKlose(raw_mm, raw_mm_ref);        % Klose eddy current correction
                        end
                        MRSCont.processed.mm_ref{mm_ref_ll,kk}       = raw_mm_ref;                          % Save back to MRSCont container
                    else
                        if MRSCont.opts.ECC.mm(mm_ref_ll,kk)
                            [raw_mm,~]                   = op_eccKlose(raw_mm, raw_ref);        % Klose eddy current correction
                        else
                            [~,raw_mm_ref]                   = op_eccKlose(raw_mm, raw_ref);        % Klose eddy current correction
                        end
                    end
                end
                if MRSCont.opts.ECC.raw(metab_ll,kk)
                    [raw,raw_ref]                   = op_eccKlose(raw, raw_ref);        % Klose eddy current correction
                else
                    try
                        [~,raw_ref]                   = op_eccKlose(raw, raw_ref);        % Klose eddy current correction
                    catch
                        [~,raw_ref]                   = op_eccKlose(raw_ref, raw_ref);        % Klose eddy current correction
                    end
                end
                [raw_ref,~]                     = op_ppmref(raw_ref,4.6,4.8,4.68);  % Reference to water @ 4.68 ppm
                MRSCont.processed.ref{metab_ll,kk}       = raw_ref;                          % Save back to MRSCont container
            end

%%          %%% 5. DETERMINE POLARITY OF SPECTRUM (EG FOR MOIST WATER SUPP) %%%
            % Automate determination whether the Cr peak has positive polarity.
            % For water suppression methods like MOIST, the residual water may
            % actually have negative polarity, but end up positive in the data, so
            % that the spectrum needs to be flipped.
            if ~isfield(MRSCont.opts.SubSpecAlignment, 'polResidCr')
                if isfield(MRSCont.opts.SubSpecAlignment, 'PreservePolarity') && ~MRSCont.opts.SubSpecAlignment.PreservePolarity
                    raw_Cr     = op_freqrange(raw,2.8,3.2);
                    % Determine the polarity of the respective peak: if the absolute of the
                    % maximum minus the absolute of the minimum is positive, the polarity
                    % of the respective peak is positive; if the absolute of the maximum
                    % minus the absolute of the minimum is negative, the polarity is negative.
                    polResidCr = abs(max(real(raw_Cr.specs))) - abs(min(real(raw_Cr.specs)));
                    polResidCr = squeeze(polResidCr);
                    polResidCr(polResidCr<0) = -1;
                    polResidCr(polResidCr>0) = 1;
                else
                    polResidCr = 1;
                end
            else
                polResidCr = MRSCont.opts.SubSpecAlignment.polResidCr;
            end
            raw = op_ampScale(raw,polResidCr);
            MRSCont.raw{metab_ll,kk} = op_ampScale(MRSCont.raw{metab_ll,kk},polResidCr);

            % Do the same for the metabolite-nulled data
            if MRSCont.flags.hasMM
                raw_Cr39    = op_freqrange(raw_mm,3.7,4.1);
                polResidCr39  = abs(max(real(raw_Cr39.specs))) - abs(min(real(raw_Cr39.specs)));
                polResidCr39(polResidCr39<0) = -1;
                polResidCr39(polResidCr39>0) = 1;
                if polResidCr39(1) ~= polResidCr(1)
                    raw_mm = op_ampScale(raw_mm,polResidCr);
                else
                    raw_mm = op_ampScale(raw_mm,polResidCr39);
                end

            end

%%          %%% 6. DETERMINE ON/OFF STATUS FOR EDITED DATA & NAMES
            % Classify the MEGA sub-spectra such that the OFF spectrum is stored in
            % the first entry , and the ON spectrum is the second entry along the
            % subspectra dimension. For HERMES and HERCULES A,B,C,D are stored
            % as first, second, third, and fourth entry, respectively.
            % Parse input arguments
            if raw.flags.isUnEdited
                raw.names = {'A'};
                MRSCont.QM.drift.pre.A{kk} = driftPre;
                MRSCont.QM.drift.post.A{kk} = driftPost;
                raw.target = {''};
            end
            if raw.flags.isMEGA
                target = MRSCont.opts.editTarget{1}; % GABA editing as default
                if isfield(MRSCont.opts, 'Order')
                    Order = MRSCont.opts.Order;
                else
                    Order = [];
                end
                [raw, switchOrder]  = osp_onOffClassifyMEGA(raw, target,Order);
                raw.names = {'A','B'};
                raw.target = MRSCont.opts.editTarget';

                if switchOrder
                    raw.flags.orderswitched = 1;
                else
                    raw.flags.orderswitched = 0;
                end
                % Save drift information back to container
                if ~switchOrder
                    MRSCont.QM.drift.pre.A{kk} = driftPre{1};
                    MRSCont.QM.drift.pre.B{kk} = driftPre{2};
                    MRSCont.QM.drift.post.A{kk} = driftPost{1};
                    MRSCont.QM.drift.post.B{kk} = driftPost{1};

                else
                    MRSCont.QM.drift.pre.A{kk} = driftPre{2};
                    MRSCont.QM.drift.pre.B{kk} = driftPre{1};
                    MRSCont.QM.drift.post.A{kk} = driftPost{2};
                    MRSCont.QM.drift.post.B{kk} = driftPost{1};
                    raw.specReg{1}.fs              = raw.specReg{1}.fs(:,[2 1]); % save align parameters
                    raw.specReg{1}.phs             = raw.specReg{1}.phs(:,[2 1]); % save align parameters
                    raw.specReg{1}.weights         = raw.specReg{1}.weights([2 1]); % save align parameters);
                end
            end
            if raw.flags.isHERMES || raw.flags.isHERCULES
                if (strcmp(MRSCont.opts.editTarget{1},'HERCULES1')||strcmp(MRSCont.opts.editTarget{1},'HERCULES2'))
                    MRSCont.opts.editTarget = {'GABA','GSH'};
                end
                target1 = MRSCont.opts.editTarget{1};
                target2 = MRSCont.opts.editTarget{2};
                if length(MRSCont.opts.editTarget) > 2
                   target3 = MRSCont.opts.editTarget{3};
                end
                if isfield(MRSCont.opts, 'Order')
                    Order = MRSCont.opts.Order;
                else
                    Order = [];
                end
                [raw, commuteOrder] = osp_onOffClassifyHERMES(raw,[target1 target2],Order);
                raw.commuteOrder = commuteOrder;
                raw.names = {'A', 'B', 'C', 'D'};
                raw.target = MRSCont.opts.editTarget';
                driftPre = driftPre(:,commuteOrder);
                driftPost = driftPost(:,commuteOrder);
                raw.specReg{1}.fs = raw.specReg{1}.fs(:,commuteOrder);
                raw.specReg{1}.phs = raw.specReg{1}.phs(:,commuteOrder);
                raw.specReg{1}.weights = raw.specReg{1}.weights(:,commuteOrder);
                % Save drift information back to container
                MRSCont.QM.drift.pre.A{kk} = driftPre{1};
                MRSCont.QM.drift.pre.B{kk} = driftPre{2};
                MRSCont.QM.drift.pre.C{kk} = driftPre{3};
                MRSCont.QM.drift.pre.D{kk} = driftPre{4};
                MRSCont.QM.drift.post.A{kk} = driftPost{1};
                MRSCont.QM.drift.post.B{kk} = driftPost{2};
                MRSCont.QM.drift.post.C{kk} = driftPost{3};
                MRSCont.QM.drift.post.D{kk} = driftPost{4};
                % Generate the drift plot for the entire experiment in
                % the correct order
                driftPre = [MRSCont.QM.drift.pre.A{kk}, MRSCont.QM.drift.pre.B{kk}, MRSCont.QM.drift.pre.C{kk}, MRSCont.QM.drift.pre.D{kk}]';
                try
                    driftPre = reshape(driftPre, [raw.averages, 1]);
                catch
                    driftPre = reshape(driftPre, [raw.rawAverages, 1]);
                end
                MRSCont.QM.drift.pre.diff1{kk}  = driftPre;
                MRSCont.QM.drift.pre.diff2{kk}  = driftPre;
                if exist('target3', 'var') % For HERMES 4 acqusitions
                    MRSCont.QM.drift.pre.diff3{kk}  = driftPre;
                end
                MRSCont.QM.drift.pre.sum{kk}    = driftPre;
                driftPost = [MRSCont.QM.drift.post.A{kk}, MRSCont.QM.drift.post.B{kk}, MRSCont.QM.drift.post.C{kk}, MRSCont.QM.drift.post.D{kk}]';
                try
                    driftPost = reshape(driftPost, [raw.averages, 1]);
                catch
                    driftPost = reshape(driftPost, [raw.rawAverages, 1]);
                end
                MRSCont.QM.drift.post.diff1{kk}  = driftPost;
                MRSCont.QM.drift.post.diff2{kk}  = driftPost;
                if exist('target3', 'var') % For HERMES 4 acqusitions
                    MRSCont.QM.drift.post.diff3{kk}  = driftPre;
                end
                MRSCont.QM.drift.post.sum{kk}    = driftPost;
            end

%%          %%% 6b. BUILD SUM AND DIFF SPECTRA %%%
            % Correct the frequency axis so that Cr appears at 3.027 ppm
            if raw.flags.isMEGA
                % Create all Hadamard combinations to generate a well defined
                % raw struct
                raw=op_HadamardScans(raw,[-1 1],'diff1');
                raw=op_HadamardScans(raw,[1 1],'sum');
                raw_no_subspec_aling = raw;
                if ~raw.flags.isMRSI
%                     [raw,~]       = op_phaseCrCho(raw, 1);
                    [refShift_SubSpecAlign, ~] = osp_XReferencing(raw,[3.03 3.22],[1 1],[1.85 4.2]);% determine frequency shift
                    if abs(refShift_SubSpecAlign) > 10 % This a huge shift. Most likley wrong and we will try it again with tNAA only
                        [refShift_SubSpecAlign, ~] = osp_XReferencing(raw,2.01,1,[1.85 4.2]);% determine frequency shift
                    end
%                     % Apply initial referencing shift
                    raw = op_freqshift(raw, -refShift_SubSpecAlign);
%                     % Fit a double-Lorentzian to the Cr-Cho area, and phase the spectrum
%                     % with the negative phase of that fit
                    [raw,ph]       = op_phaseCrCho(raw, 1);

                else
                    refShift_SubSpecAlign =0;
                end

                switch MRSCont.opts.SubSpecAlignment.mets
                    case 'L1Norm'
                        [raw]  = osp_editSubSpecAlignLNorm(raw,seq);
                    case 'L2Norm'
                        [raw]  = osp_editSubSpecAlign(raw, seq, target,MRSCont.opts.UnstableWater);
                    otherwise
                end

                if MRSCont.flags.hasMM
                    raw_mm=op_HadamardScans(raw_mm,[-1 1],'diff1');
%                     diff1_mm = op_takesubspec(raw_mm,3);
%                     [diff1_mm,~]          = op_autophase(diff1_mm,0.5,1.1);
%                     raw_mm = op_mergesubspec(raw_mm,diff1_mm);
%                     [refShift_mm, ~] = fit_OspreyReferencingMM(raw_mm);
%                     [raw_mm]             = op_freqshift(raw_mm,-refShift_mm);
                    switch MRSCont.opts.SubSpecAlignment.mm
                        case 'L1Norm'
                        [raw_mm]  = osp_editSubSpecAlignLNorm(raw_mm,seq);
                        case 'L2Norm'
                        [raw_mm]  = osp_editSubSpecAlign(raw_mm, seq, target,MRSCont.opts.UnstableWater);
                        otherwise
                    end
                    if switchOrder
                        raw_mm.flags.orderswitched = 1;
                    else
                        raw_mm.flags.orderswitched = 0;
                    end
                    raw_mm=op_HadamardScans(raw_mm,[-1 1],'diff1');
                    raw_mm=op_HadamardScans(raw_mm,[1 1],'sum');
                end
                % Create the edited difference spectrum
                raw=op_HadamardScans(raw,[-1 1],'diff1');
                % Create the sum spectrum
                raw=op_HadamardScans(raw,[1 1],'sum');
                raw.target = target;
                raw = op_freqshift(raw, refShift_SubSpecAlign);
            end

            if raw.flags.isHERMES || raw.flags.isHERCULES
                % Create all Hadamard combinations to generate a well defined
                % raw struct
                if ~exist('target3', 'var')
                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
                else  % For HERMES 4 acqusitions
                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
                    raw=op_HadamardScans(raw,[-1 1 1 -1],'diff3');
                end
                raw=op_HadamardScans(raw,[1 1 1 1],'sum');
                raw_no_subspec_aling = raw;

                % Correct the frequency axis so that Cr appears at 3.027 ppm
                [refShift_SubSpecAlign, ~] = osp_XReferencing(raw,[3.03 3.22],[1 1],[1.85 3.9]);% determine frequency shift
                if abs(refShift_SubSpecAlign) > 10 % This a huge shift. Most likley wrong and we will try it again with tNAA only
                    [refShift_SubSpecAlign, ~] = osp_XReferencing(raw,2.01,1,[1.85 3.9]);% determine frequency shift
                end

                % Apply initial referencing shift
                raw = op_freqshift(raw, -refShift_SubSpecAlign);
                % Fit a double-Lorentzian to the Cr-Cho area, and phase the spectrum
                % with the negative phase of that fit
                [raw,~] = op_phaseCrCho(raw, 1);
                % Align the sub-spectra to one another by minimizing the difference
                % between the common 'reporter' signals.
                switch MRSCont.opts.SubSpecAlignment.mets
                    case 'L1Norm'
                        [raw]  = osp_editSubSpecAlignLNorm(raw,seq);
                    case 'L2Norm'
                        if ~exist('target3', 'var')
                            [raw]  = osp_editSubSpecAlign(raw, seq, target1,target2,MRSCont.opts.UnstableWater);
                        else
                            if strcmp(target3,'EtOH')
                                [raw]  = osp_editSubSpecAlign(raw, seq, target1,target3,MRSCont.opts.UnstableWater);
                            else
                               [raw]  = osp_editSubSpecAlign(raw, seq, target2,target3,MRSCont.opts.UnstableWater); 
                            end
                        end
                    otherwise
                end
                % Update all Hadamard combinations after subspectra alignment
                if ~exist('target3', 'var')
                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
                else  % For HERMES 4 acqusitions
                    raw=op_HadamardScans(raw,[-1 1 -1 1],'diff1');
                    raw=op_HadamardScans(raw,[-1 -1 1 1],'diff2');
                    raw=op_HadamardScans(raw,[-1 1 1 -1],'diff3');
                end
                raw=op_HadamardScans(raw,[1 1 1 1],'sum');
                raw = op_freqshift(raw, refShift_SubSpecAlign);
                fields.Method   = 'Addition of sub-spectra';
                if raw.flags.isHERCULES
                    fields.Details  = ['HERCULES Hadmard combination (Oeltzschner et al. 2019)'];
                else
                    fields.Details  = ['HERMES Hadmard combination (Saleh et al. 2018)'];
                end
                raw = op_add_analysis_provenance(raw,fields);

            end

%%          %%% 7. REMOVE RESIDUAL WATER %%%
            % Define different water removal frequency ranges, depending on
            % whether this is phantom data
            if MRSCont.flags.isPhantom
                waterRemovalFreqRange = [4.5 5];
                fracFID = 0.2;
            else
                waterRemovalFreqRange = [4.2 4.9];
                fracFID = 0.75;
            end
            % Apply iterative water filter
            raw = op_iterativeWaterFilter(raw, waterRemovalFreqRange, 32, fracFID*length(raw.fids), 0);
            if exist('raw_no_subspec_aling','var')
                raw_no_subspec_aling = op_iterativeWaterFilter(raw_no_subspec_aling, waterRemovalFreqRange, 32, fracFID*length(raw.fids), 0);
            end

            if MRSCont.flags.hasMM %re_mm
                raw_mm = op_iterativeWaterFilter(raw_mm, waterRemovalFreqRange, 32, fracFID*length(raw_mm.fids), 0);
            end

%%          %%% 8. REFERENCE SPECTRUM CORRECTLY TO FREQUENCY AXIS AND PHASE SIEMENS
            %%% DATA
            if MRSCont.flags.isPhantom
                [refShift, ~, ~] = osp_PhantomReferencing(raw);
            else
                [refShift, ~] = osp_XReferencing(raw,[3.03 3.22],[1 1],[1.85 4.2]);% determine frequency shift
                if abs(refShift) > 10 % This a huge shift. Most likley wrong and we will try it again with tNAA only
                    [refShift, ~] = osp_XReferencing(raw,2.01,1,[1.85 4.2]);% determine frequency shift
                end
            end
            [raw]             = op_freqshift(raw,-refShift);            % Reference spectra by cross-correlation
            if exist('raw_no_subspec_aling','var')
                [raw_no_subspec_aling]             = op_freqshift(raw_no_subspec_aling,-refShift);            % Reference spectra by cross-correlation
            end

            if MRSCont.flags.hasMM %re_mm
                if raw_mm.flags.isMEGA
                    temp = op_takesubspec(raw_mm,3);
                    [temp,~]          = op_autophase(temp,0.5,1.1);
                    raw_mm = op_mergesubspec(raw_mm,temp);
                end
                [refShift_mm, ~] = fit_OspreyReferencingMM(raw_mm);
                [raw_mm]             = op_freqshift(raw_mm,-refShift_mm);            % Reference spectra by cross-correlation
            end

            % Save back to MRSCont container
            if (strcmp(MRSCont.vendor,'Siemens') && raw.flags.isUnEdited && ~MRSCont.flags.isPhantom) || MRSCont.flags.isMRSI
                % Fit a double-Lorentzian to the Cr-Cho area, and phase the spectrum
                % with the negative phase of that fit
                [raw,globalPhase]       = op_phaseCrCho(raw, 1);
                raw.specReg{1}.phs = raw.specReg{1}.phs - globalPhase*180/pi;
            end

%%          %%% 9. QUALITY CONTROL PARAMETERS %%%
            SubSpec = raw.names;
            % Calculate some spectral quality metrics here;
            [raw,SNR] = op_get_Multispectra_SNR(raw);
            FWHM = op_get_Multispectra_LW(raw);
            MRSCont.processed.metab{metab_ll,kk}     = raw;
            if exist('raw_no_subspec_aling','var')
                MRSCont.processed_no_align.metab{metab_ll,kk}     = raw_no_subspec_aling;
            end
            for ss = 1 : length(SubSpec)
                MRSCont.QM.SNR.metab(metab_ll,kk,ss)    = SNR{ss};
                MRSCont.QM.FWHM.metab(metab_ll,kk,ss)   = FWHM(ss); % in Hz
                MRSCont.QM.freqShift.metab(metab_ll,kk,ss)  = refShift;
                MRSCont.QM.res_water_amp.metab(metab_ll,kk,ss) = sum(MRSCont.processed.metab{kk}.watersupp{ss}.amp);
                if strcmp(SubSpec{ss},'diff1') ||strcmp(SubSpec{ss},'diff2') || strcmp(SubSpec{ss},'diff3') ||strcmp(SubSpec{ss},'sum')
                    if raw.flags.isMEGA
                        MRSCont.QM.drift.pre.(SubSpec{ss}){metab_ll,kk}  = reshape([MRSCont.QM.drift.pre.A{kk}'; MRSCont.QM.drift.pre.B{kk}'], 1, [])';
                        MRSCont.QM.drift.post.(SubSpec{ss}){metab_ll,kk} = reshape([MRSCont.QM.drift.post.A{kk}'; MRSCont.QM.drift.post.B{kk}'], 1, [])';
                    else
                        MRSCont.QM.drift.pre.(SubSpec{ss}){metab_ll,kk}  = reshape([MRSCont.QM.drift.pre.A{kk}'; MRSCont.QM.drift.pre.B{kk}'; MRSCont.QM.drift.pre.C{kk}'; MRSCont.QM.drift.pre.D{kk}'], 1, [])';
                        MRSCont.QM.drift.post.(SubSpec{ss}){metab_ll,kk} = reshape([MRSCont.QM.drift.post.A{kk}'; MRSCont.QM.drift.post.B{kk}'; MRSCont.QM.drift.post.C{kk}'; MRSCont.QM.drift.post.D{kk}'], 1, [])';
                    end
                end
                MRSCont.QM.drift.pre.AvgDeltaCr.(SubSpec{ss})(metab_ll,kk) = mean(MRSCont.QM.drift.pre.(SubSpec{ss}){kk} - 3.02);
                MRSCont.QM.drift.post.AvgDeltaCr.(SubSpec{ss})(metab_ll,kk) = mean(MRSCont.QM.drift.post.(SubSpec{ss}){kk} - 3.02);
            end
            if MRSCont.flags.hasMM
                SubSpec = raw_mm.names;
                [raw_mm,SNR] = op_get_Multispectra_SNR(raw_mm,1);
                FWHM = op_get_Multispectra_LW(raw_mm);
                MRSCont.processed.mm{ll,kk}     = raw_mm;
                for ss = 1 : length(SubSpec)
                    MRSCont.QM.SNR.mm(mm_ll,kk,ss)    = SNR{ss};
                    MRSCont.QM.FWHM.mm(mm_ll,kk,ss)   = FWHM(ss);
                end
            end
            if MRSCont.flags.hasRef
                MRSCont.QM.SNR.ref(ref_ll,kk)    = op_getSNR(MRSCont.processed.ref{kk});
                MRSCont.QM.FWHM.ref(ref_ll,kk)   = op_getLW(MRSCont.processed.ref{kk},4.2,5.2);
                MRSCont.processed.ref{kk}.QC_names = {'water'};
            end
            if MRSCont.flags.hasWater
                MRSCont.QM.SNR.w(w_ll,kk)    = op_getSNR(MRSCont.processed.w{kk});
                MRSCont.QM.FWHM.w(w_ll,kk)   = op_getLW(MRSCont.processed.w{kk},4.2,5.2);
                MRSCont.processed.w{kk}.QC_names = {'water'};
            end
            if MRSCont.flags.hasMMRef
                MRSCont.QM.SNR.mm_ref(mm_ref_ll,kk)    = op_getSNR(MRSCont.processed.mm_ref{kk});
                MRSCont.QM.FWHM.mm_ref(mm_ref_ll,kk)   = op_getLW(MRSCont.processed.mm_ref{kk},4.2,5.2);
                MRSCont.processed.mm_ref{kk}.QC_names = {'water'};
            end
        end
    end
end


