% op_firstPointPhase.m
% Georg Oeltzschner, Johns Hopkins University 2019.
% 
% USAGE:
% [out]=op_firstPointPhase(in);
% 
% DESCRIPTION:
% Performs a zero-order phase correction by multiplying each point of the
% FID with the normalized complex conjugate of the first point.
% 
% INPUTS:
% in         = input data in matlab structure format.  
%
% OUTPUTS:
% out        = Output following first-point phasing.

function [out]=op_firstPointPhase(in);

% Duplicate input structure
out = in;

% Determine phase correction
fids    = in.fids;
sz      = in.sz;
corrph = conj(fids(1,:))./abs(fids(1,:));
corrph = repmat(corrph, [sz(1) 1]);
if length(sz) == 2
    corrph = reshape(corrph, [sz(1) sz(2)]);
elseif length(sz) == 3
    corrph = reshape(corrph, [sz(1) sz(2) sz(3)]);
end

% Apply phase correction
fids = fids .* corrph;

% Produce specs
specs = fftshift(fft(fids,[],in.dims.t),in.dims.t);

%FILLING IN DATA STRUCTURE
out.specs   = specs;
out.fids    = fids;




% philipsLoad.m
% Georg Oeltzschner, Johns Hopkins University 2018.
%
% USAGE:
% [data, header] = philipsLoad(filename);
% 
% DESCRIPTION:
% Reads in philips MRS data (.spar and .sdat files) using code adapted from 
% PhilipsRead.m, provided as part of the Gannet software package by Richard 
% Edden (gabamrs.com).
% 
% INPUTS:
% filename   = filename of Philips .sdat file to be loaded.
%
% OUTPUTS:
% data       = FID array.
% header     = Structure containing header information from SPAR file.

function [data, header] = philipsLoad(filename)

% Get the .spar filename
sparname = [filename(1:(end-4)) 'spar'];
% Populate the header information from the SPAR file
% Look for regular expression separated by a colon
fid_spar = fopen(sparname);
if fid_spar == -1
    sparname = [filename(1:(end-4)) 'SPAR']; %This seems to be a problem for some Linux based systems
    fid_spar = fopen(sparname);
end
while ~feof(fid_spar)
    tline = fgets(fid_spar); % get first line
    [tokens,matches] = regexp(tline,'([\w\[\].]*)\s*:\s*([-\w\s.\"\\:\.]*)','tokens','match');
        % When a matching string is found, parse the results into a struct
        if length(tokens) == 1
            fieldname = regexprep(tokens{1}{1}, '\[|\]',''); % delete invalid characters

            % Convert numbers to doubles, leave strings & empty lines alone
            if ~isnan(str2double(tokens{1}{2}))
                value = str2double(tokens{1}{2});
            else
                value = tokens{1}{2};
            end

            header.(fieldname) = value;

        end
end
fclose(fid_spar);

% Now open the SDAT file and read in the data
fid_sdat    = fopen(filename,'r','ieee-le');
sdat_length = length(fread(fid_sdat));
fclose(fid_sdat);
fid_sdat    = fopen(filename,'r','ieee-le');
data        = freadVAXG(fid_sdat,sdat_length,'float32');
fclose(fid_sdat);
% Reshape and save
if isfield(header, 'nr_of_slices_for_multislice') && header.nr_of_slices_for_multislice > 1
    data        = reshape(data, [2 header.samples header.rows header.nr_of_slices_for_multislice]);
    data        = squeeze(data(1,:,:,:)+1i*data(2,:,:,:));
else
    data        = reshape(data, [2 header.samples header.rows]);    
    data        = squeeze(data(1,:,:)+1i*data(2,:,:));
end
end

% op_ampScale.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_ampScale(in,A);
% 
% DESCRIPTION:
% Scale the amplitude of a spectrum by factor A.
% 
% INPUTS:
% in    = input data in matlab structure format
% A     = Amplitude scaling factor.
%
% OUTPUTS:
% out   = Output following amplitude scaling.  

function out=op_ampScale(in,A);

sz_A = length(A);
out=in;
if sz_A == 1
    out.specs=in.specs*A;
    out.fids=in.fids*A;
else

    if in.dims.averages==0   
        for ss = 1 : out.sz(end)
            out.specs(:,ss)=in.specs(:,ss)*A(ss);
            out.fids(:,ss)=in.fids(:,ss)*A(ss);
        end
    else
        for ss = 1 : out.sz(end)
            out.specs(:,:,ss)=in.specs(:,:,ss)*A(ss);
            out.fids(:,:,ss)=in.fids(:,:,ss)*A(ss);
        end
    end
end

% op_takesubspec.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_takesubspec(in,index);
% 
% DESCRIPTION:
% Extract the subspectra with indices corresponding to the 'index' input
% array. 
% 
% INPUTS:
% in     = input data in matlab structure format.
% index  = vector indicating the indices of the subspectra you would like 
%          to extract.
%
% OUTPUTS:
% out    = Output dataset consisting of subspectra indices extracted from 
%          the input.

function out=op_takesubspec(in,index);

if ~isnumeric(index)
    index = find(strcmp(in.names,index));
    if isempty(index)
        index = 1;
    end
end

if in.flags.subtracted && ~strcmp(in.seq, 'SPECIAL')
    error('ERROR:  Subspectra have already been combined!  Aborting!');
end
% in.fids = squeeze(in.fids);
if in.dims.subSpecs==0
    %Can't take subspec because there are none:
    if index > 1
        error('ERROR:  There are no subspectra in this dataset!  Aborting!');
    else
        fids = in.fids;
    end
elseif in.dims.subSpecs==1
    %SHOULD NEVER HAPPEN (Time dimension should always be dim=1)
    error('ERROR:  dims.subSpecs==1.  This should never happen!  Aborting!');
elseif in.dims.subSpecs==2
    fids=in.fids(:,index,:,:,:);
elseif in.dims.subSpecs==3;
    fids=in.fids(:,:,index,:,:,:);
elseif in.dims.subSpecs==4;
    fids=in.fids(:,:,:,index,:,:,:);
elseif in.dims.subSpecs==5
    fids=in.fids(:,:,:,:,index,:,:,:);
end

%re-calculate Specs using fft
specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

%change the dims variables
if in.dims.t>in.dims.subSpecs && in.dims.subSpecs ~=0
    dims.t=in.dims.t-1;
else
    dims.t=in.dims.t;
end
if in.dims.coils>in.dims.subSpecs && in.dims.subSpecs ~=0
    dims.coils=in.dims.coils-1;
else
    dims.coils=in.dims.coils;
end
if in.dims.averages>in.dims.subSpecs && in.dims.subSpecs ~=0
    dims.averages=in.dims.averages-1;
else
    dims.averages=in.dims.averages;
end
if in.dims.extras>in.dims.subSpecs && in.dims.subSpecs ~=0
    dims.extras=in.dims.extras-1;
else
    dims.extras=in.dims.extras;
end
dims.subSpecs=0;

%re-calculate the sz variable
sz=size(fids);


%FILLING IN DATA STRUCTURE
out=in;
out.fids=fids;
out.specs=specs;
out.sz=sz;
out.dims=dims;
if ~out.flags.averaged
    try
        out.averages = out.sz(out.dims.averages);
    catch
        out.averages = out.sz(2);
    end
end
out.subspecs=1;
if isfield(out, 'names')
    out.names = out.names(index);
end
%FILLING IN THE FLAGS
out.flags=in.flags;
out.flags.writtentostruct=1;
out.flags.isFourSteps=0;
% op_mergesubspec.m
% Helge Zoellner, Johns Hopkins University 2021.
% 
% USAGE:
% out=op_mergesubspec(varargin);
% 
% DESCRIPTION:
% Merges input structs into the subspectra dimension
% 
% INPUTS:
% varargin     = input data in matlab structure format.
%
% OUTPUTS:
% out    = Output dataset with merged subspectra

function out=op_mergesubspec(varargin);
in1 = varargin{1};

if isempty(varargin{2}) %Check if the first argument to be a null string
    error('You have to at least put in two structs')
else

    for ss = 2 : length(varargin)
        in2 = varargin{ss};
        if in1.dims.subSpecs~=0 && in2.dims.subSpecs~=0 && in1.dims.subSpecs ~= in2.dims.subSpecs
            %RULE:  Averages dimension must be the same for both inputs UNLESS one of
            %the inputs has an averages dimension of zero:
            error('subspectra dimensions must be the same for both inputs');
        end

        if in1.dims.subSpecs==0 && in2.dims.subSpecs==0
            dim=2;
        elseif in1.dims.subSpecs==0
            dim=in2.dims.subSpecs;
        elseif in2.dims.averages==0;
            dim=in1.dims.subSpecs;
        else
            dim=in1.dims.subSpecs;
        end
        if ~contains(in1.names,in2.names(1))
            in1.fids=cat(dim,in1.fids,in2.fids);
            in1.specs=cat(dim,in1.specs,in2.specs);
            in1.subspecs=in1.subspecs+in2.subspecs;
            in1.names{end+1} = in2.names{1};
        else
            ind = find(strcmp(in1.names,in2.names(1)));
            in1.fids(:,ind,:,:,:,:,:) = in2.fids(:,1,:,:,:,:,:);
            in1.specs(:,ind,:,:,:,:,:) = in2.specs(:,1,:,:,:,:,:);
        end

    end
    sz=size(in1.fids);

    %FILLING IN DATA STRUCTURE
    out=in1;
    out.sz=sz;
%     out.rawAverages=in1.rawAverages+in2.rawAverages;
    if in1.dims.subSpecs==0
        out.dims.subSpecs=dim;
    end


    %FILLING IN THE FLAGS
    out.flags=in1.flags;
    out.flags.writtentostruct=1;
end

