function result = task005_evaluate(source_root, fixture_path)
% Run the public edited-MRS loading experiment against the current source tree.

case_data = task005_load_case(fixture_path);
[ppm, spectra] = task005_build_spectra(case_data);
input_observation = task005_observe_spectra(ppm, spectra, case_data);
loaded_workflow = task005_run_loaded_workflow(source_root, ppm, spectra, case_data);

result.case_name = case_data.name;
result.num_subspectra = columns(spectra);
result.input_observation = input_observation;
result.loaded_workflow = loaded_workflow;
result.workflow_completed = loaded_workflow.workflow_completed;
end

function case_data = task005_load_case(fixture_path)
if exist(fixture_path, 'file') ~= 2
    error('sciencebench:task005:FixtureMissing', 'Public fixture not found: %s', fixture_path);
end

decoded = jsondecode(fileread(fixture_path));
scalar_fields = {
    'num_points', 'ppm_min', 'ppm_max', 'reference_center_ppm', ...
    'reference_width_ppm', 'edited_center_ppm', 'edited_width_ppm'
};
for idx = 1:numel(scalar_fields)
    field_name = scalar_fields{idx};
    if ~isfield(decoded, field_name)
        error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: %s', field_name);
    end
    value = decoded.(field_name);
    if ~isnumeric(value) || numel(value) ~= 1 || ~isfinite(value)
        error('sciencebench:task005:FixtureProtocol', 'Fixture field %s must be one finite number.', field_name);
    end
    case_data.(field_name) = double(value);
end

if ~isfield(decoded, 'name')
    error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: name');
end
case_data.name = char(decoded.name);

vector_fields = {'reference_amplitudes', 'edited_amplitudes', 'phase_degrees'};
for idx = 1:numel(vector_fields)
    field_name = vector_fields{idx};
    if ~isfield(decoded, field_name)
        error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: %s', field_name);
    end
    value = double(decoded.(field_name));
    if ~isnumeric(value) || isempty(value) || any(~isfinite(value(:)))
        error('sciencebench:task005:FixtureProtocol', 'Fixture field %s must contain finite numbers.', field_name);
    end
    case_data.(field_name) = reshape(value, 1, []);
end

nsubs = numel(case_data.reference_amplitudes);
if numel(case_data.edited_amplitudes) ~= nsubs || numel(case_data.phase_degrees) ~= nsubs
    error('sciencebench:task005:FixtureProtocol', 'Fixture subspectrum arrays must have equal lengths.');
end
if case_data.num_points < 16 || case_data.ppm_max <= case_data.ppm_min
    error('sciencebench:task005:FixtureProtocol', 'Fixture spectral grid is invalid.');
end
if case_data.reference_width_ppm <= 0 || case_data.edited_width_ppm <= 0
    error('sciencebench:task005:FixtureProtocol', 'Fixture peak widths must be positive.');
end
end

function [ppm, spectra] = task005_build_spectra(case_data)
npts = case_data.num_points;
ppm = linspace(case_data.ppm_min, case_data.ppm_max, npts)';
reference_shape = exp(-0.5 .* ((ppm - case_data.reference_center_ppm) ./ case_data.reference_width_ppm) .^ 2);
edited_shape = exp(-0.5 .* ((ppm - case_data.edited_center_ppm) ./ case_data.edited_width_ppm) .^ 2);

nsubs = numel(case_data.reference_amplitudes);
spectra = zeros(npts, nsubs);
for idx = 1:nsubs
    phase = case_data.phase_degrees(idx) * pi / 180;
    signal = case_data.reference_amplitudes(idx) .* reference_shape + ...
        case_data.edited_amplitudes(idx) .* edited_shape;
    spectra(:, idx) = real(signal .* complex(cos(phase), sin(phase)));
end
end

function metrics = task005_observe_spectra(ppm, spectra, case_data)
mask = task005_reference_mask(ppm, case_data.reference_center_ppm, case_data.reference_width_ppm);
window = real(spectra(mask, :));

polarities = zeros(1, columns(window));
for idx = 1:columns(window)
    polarities(idx) = task005_estimate_polarity(window(:, idx));
end
sign_consistency = mean(polarities == polarities(1));

norms = zeros(1, columns(window));
for idx = 1:columns(window)
    norms(idx) = norm(window(:, idx));
end
retained = norm(mean(window, 2)) / max(mean(norms), 1e-12);

metrics.reference_sign_consistency = sign_consistency;
metrics.retained_common_signal_ratio = retained;
metrics.reference_peak_polarity_consistent = all(polarities == polarities(1));
metrics.observations_finite = isfinite(sign_consistency) && isfinite(retained);
end

function mask = task005_reference_mask(ppm, center, width)
mask = abs(ppm - center) <= max(width * 3.5, 0.08);
end

function polarity = task005_estimate_polarity(spec)
[~, idx] = max(abs(real(spec)));
if real(spec(idx)) >= 0
    polarity = 1.0;
else
    polarity = -1.0;
end
end

function workflow = task005_run_loaded_workflow(source_root, ppm, spectra, case_data)
workflow = struct;

input_dir = fullfile(fileparts(source_root), 'outputs', 'public_sdat_study');
if ~exist(input_dir, 'dir')
    mkdir(input_dir);
end

addpath(fullfile(source_root, 'libraries', 'FID-A', 'inputOutput'));
data_path = task005_write_loader_fixture(input_dir, spectra);

loaded = io_loadspec_sdat(data_path, columns(spectra), 0);
if ~task005_valid_loaded_struct(loaded, columns(spectra))
    error('sciencebench:task005:LoaderProtocol', 'SDAT loader returned an invalid or non-finite payload.');
end

loaded_spectra = task005_average_loaded_spectra(loaded);
if rows(loaded_spectra) ~= numel(ppm) || columns(loaded_spectra) ~= columns(spectra)
    error('sciencebench:task005:LoaderProtocol', 'SDAT loader returned an unexpected spectral shape.');
end

workflow.observation = task005_observe_spectra(ppm, loaded_spectra, case_data);
if ~workflow.observation.observations_finite
    error('sciencebench:task005:LoaderProtocol', 'SDAT loader observations were non-finite.');
end
workflow.loaded_output_valid = true;
workflow.workflow_completed = true;
end

function ok = task005_valid_loaded_struct(value, expected_subspecs)
ok = isstruct(value) && isfield(value, 'fids') && isfield(value, 'specs') && ...
    isfield(value, 'dims') && isfield(value, 'subspecs') && value.subspecs == expected_subspecs && ...
    all(isfinite(value.fids(:))) && all(isfinite(value.specs(:)));
end

function spectra = task005_average_loaded_spectra(loaded)
spectra = loaded.specs;
if isfield(loaded.dims, 'averages') && loaded.dims.averages > 0
    spectra = mean(spectra, loaded.dims.averages);
end
spectra = squeeze(spectra);
if isvector(spectra)
    spectra = spectra(:);
end
end

function data_path = task005_write_loader_fixture(input_dir, spectra)
data_path = fullfile(input_dir, 'public_loader.sdat');
spar_path = fullfile(input_dir, 'public_loader.spar');

samples = rows(spectra);
subspecs = columns(spectra);
averages_per_subspec = 2;
rows_in_file = subspecs * averages_per_subspec;
source_fids = ifft(ifftshift(spectra, 1), [], 1);
fid_data = zeros(samples, rows_in_file);
for average_index = 1:averages_per_subspec
    for subspec_index = 1:subspecs
        row_index = (average_index - 1) * subspecs + subspec_index;
        fid_data(:, row_index) = source_fids(:, subspec_index);
    end
